export const bnAbout3: Record<string, string> = {
	'amrita-institute-of-medical-sciences-kochi':
		"##history\nকোচির Ponekkara-তে অমৃতা হাসপাতাল, পূর্বে Amrita Institute of Medical Sciences (AIMS), ১৯৯৮ সালের ১৭ মে মাতা অমৃতানন্দময়ী দেবী (আম্মা) প্রতিষ্ঠা করেন একটি মাল্টিস্পেশালিটি টারশিয়ারি রেফারেল ও শিক্ষাদান হাসপাতাল হিসেবে। এটি ২০১৩ সালে দেশের সেরা হাসপাতালের জন্য FICCI National Healthcare Excellence Award এবং ২০১৬ সালে রোগীর নিরাপত্তা ও মেডিক্যাল প্রযুক্তিতে উদ্ভাবনের জন্য আরও দুটি FICCI পুরস্কার পেয়েছে। এটি NABH দ্বারা স্বীকৃত, ল্যাবরেটরি NABL দ্বারা স্বীকৃত।\n##specialities\nহাসপাতালটিতে ২৯টি বিশেষত্ব বিভাগ ও ১৭টি উৎকর্ষ কেন্দ্র রয়েছে, প্রায় ৬৭০ জন অনুষদ সদস্য ও ৪,০০০ সহায়ক কর্মীর সহায়তায়, বছরে ১০ লক্ষেরও বেশি বহির্বিভাগ রোগী ও ৭০,০০০-এরও বেশি ভর্তি রোগীর সেবা দেয়। মাইলফলকের মধ্যে রয়েছে কেরালার প্রথম একযোগে প্যানক্রিয়াস-কিডনি প্রতিস্থাপন (2014), দক্ষিণ এশিয়ার প্রথম দ্বিপাক্ষিক হাত প্রতিস্থাপন (2015), এবং ২০২১ সালে, HEMO2life গ্রাফট সংরক্ষণ প্রযুক্তি ব্যবহার করে প্রথম দুই উপরের অঙ্গের প্রতিস্থাপন, এটির নবম এই ধরনের সার্জারি। পরিষেবা ট্রান্সফিউশন মেডিসিন ও ইউরোলজি থেকে ক্র্যানিওম্যাক্সিলোফেসিয়াল সার্জারি ও ডার্মাটোলজি এবং কসমেটোলজি পর্যন্ত বিস্তৃত।\n##technology\nবিভিন্ন সূত্র অনুযায়ী হাসপাতালটিতে প্রায় ১,১০০ থেকে ১,৪৫০ শয্যা রয়েছে, যা এটিকে দক্ষিণ ভারতের অন্যতম বৃহত্তম করে তোলে। এটি কোচির Ponekkara-তে একটি বড় ক্যাম্পাসে অবস্থিত।\n##international\nঅমৃতায় একটি নিবেদিত দল রয়েছে যা আন্তর্জাতিক রোগীদের চিকিৎসা সমন্বয় করে, মেডিক্যাল ভিসা ও থাকার সহায়তা, চিকিৎসা ও খরচের উপর প্রাক-ভিজিট মেডিক্যাল মতামত এবং বহুভাষিক দোভাষী সহ।",
	'aster-medcity':
		"##history\nকোচির Cheranalloor-এ Aster Medcity Aster DM Healthcare ২০১৩ সালে প্রতিষ্ঠা করে এবং ২০১৪ সালে সফট লঞ্চ হিসেবে কার্যক্রম শুরু করে। এটি কোচির ব্যাকওয়াটারের তীরে ৪০ একরের একটি ক্যাম্পাসে অবস্থিত এবং দক্ষিণ এশিয়ার অন্যতম বৃহত্তম কোয়াটারনারি-কেয়ার স্বাস্থ্যসেবা কেন্দ্র। এটি কেরালার প্রথম JCI-স্বীকৃত কোয়াটারনারি-কেয়ার মাল্টিস্পেশালিটি হাসপাতাল, এবং এর প্রথম বছরেই NABH স্বীকৃতি, NABH নার্সিং এক্সেলেন্স সার্টিফিকেশন ও Green OT সার্টিফিকেশনও অর্জন করে।\n##specialities\nAster Medcity একটি মাল্টিস্পেশালিটি হাসপাতাল যার আটটি উৎকর্ষ কেন্দ্র রয়েছে, নিউরোসায়েন্স, কার্ডিয়াক সায়েন্স, অর্থোপেডিক্স, অনকোলজি, গ্যাস্ট্রোএন্টারোলজি, নেফ্রোলজি, ইউরোলজি, নারী স্বাস্থ্য, শিশুরোগ, নবজাতকবিদ্যা ও মাল্টি-অর্গান প্রতিস্থাপনসহ। হেপাটোলজিস্ট, নেফ্রোলজিস্ট, প্রতিস্থাপন সার্জন ও ইনটেনসিভিস্টদের একটি বহু-শাখা প্রতিস্থাপন দল কিডনি, লিভার, হৃদয় ও সমন্বিত প্রতিস্থাপন পরিচালনা করে। এটি কেরালার প্রথম হাসপাতাল বলে জানা যায় যা da Vinci সিস্টেম দিয়ে মিনিমাল অ্যাক্সেস রোবোটিক সার্জারি প্রদান করে, প্রতিস্থাপন, ইউরোলজি ও স্ত্রীরোগে ৫,০০০-এরও বেশি রোবোট-সহায়তায় সার্জারির কথা জানানো হয়েছে।\n##technology\nহাসপাতালটি একটি বৃহৎ কোয়াটারনারি-কেয়ার প্রতিষ্ঠান যার কয়েকশ শয্যা রয়েছে; সূত্র প্রায় ৬৭০ থেকে ৮০০ উল্লেখ করে। এর ক্যাম্পাসটি রোগীর আরামের জন্য ডিজাইন করা হয়েছে, সবুজ সার্টিফিকেশনসহ।\n##international\nAster Medcity দক্ষিণ ভারতে মেডিক্যাল ভ্রমণকারীদের জন্য একটি সুপরিচিত গন্তব্য। Cheranalloor কোচি শহরের কাছাকাছি এবং কোচিন আন্তর্জাতিক বিমানবন্দর থেকে প্রায় ২৫-৩০ কিমি দূরে।",
	'lakeshore-hospital':
		"##history\nকোচির Nettoor-এ NH-66 বাইপাসে VPS Lakeshore হাসপাতাল একটি মাল্টি-সুপার স্পেশালিটি হাসপাতাল যা ২০০৩ সালের জানুয়ারিতে একটি মাল্টিস্পেশালিটি হাসপাতাল হিসেবে কার্যক্রম শুরু করে। এটি NABH দ্বারা স্বীকৃত এবং মেডিক্যাল ট্যুরিজমের জন্য একটি শীর্ষস্থানীয় গন্তব্য হিসেবে বর্ণিত হয়েছে। এটি ২০১৪ সালে কেরালা সরকারের কাছ থেকে মেডিক্যাল ট্যুরিজমের জন্য সেরা হাসপাতাল পুরস্কার, ২০১৬ সালে Worldwide Achievers থেকে কেরালার সেরা হাসপাতাল পুরস্কার এবং ২০১৭ সালে Times of India থেকে অনকোলজি পরিষেবায় সেরা হাসপাতাল পুরস্কার পেয়েছে।\n##specialities\nহাসপাতালটিতে মাল্টি-অর্গান প্রতিস্থাপন, গ্যাস্ট্রোএন্টারোলজি, জয়েন্ট রিপ্লেসমেন্ট, কার্ডিওলজি, কার্ডিওভাস্কুলার সার্জারি ও নিউরোলজিসহ ৩০টিরও বেশি ক্লিনিক্যাল বিভাগ রয়েছে। এর নেফ্রোলজি ও কিডনি প্রতিস্থাপন বিভাগ ১,৬০০-এরও বেশি প্রতিস্থাপন করেছে, এবং এর কার্ডিয়াক সায়েন্স কেন্দ্রে হৃদ-প্রতিস্থাপন ও ECMO অন্তর্ভুক্ত। মাইলফলকের মধ্যে রয়েছে কেরালার প্রথম লিভার প্রতিস্থাপন, প্রথম শিশু বোন ম্যারো প্রতিস্থাপন, রাজ্যের প্রথম রোবোটিক নী রিপ্লেসমেন্ট সিস্টেম এবং কেরালার প্রথম বিমান, জল ও স্থল অ্যাম্বুলেন্স পরিষেবা, Limca Book of Records দ্বারা স্বীকৃত।\n##technology\nহাসপাতালটিতে কয়েকশ শয্যা রয়েছে, সূত্র প্রায় ৪৭০ থেকে ৬৫০ উল্লেখ করে, এবং এটি অঙ্গ প্রতিস্থাপন, হৃদযত্ন ও মিনিমালি ইনভেসিভ সার্জারিতে শীর্ষস্থানীয়।\n##international\nহাসপাতালটি ২৪-ঘণ্টা অতিথি সম্পর্ক, আন্তর্জাতিক রোগীদের জন্য অগ্রিম অর্থপ্রদানের বিকল্প, কাস্টমাইজড রন্ধনপ্রণালী, বহুভাষিক কর্মী এবং বিদেশি মুদ্রা গ্রহণ প্রদান করে।",
	'kims-health-kochi':
		"##history\nKIMS Health, Kochi, তিরুবনন্তপুরম-ভিত্তিক KIMS গ্রুপের প্রতিষ্ঠানের কোচি হাসপাতাল, যার মধ্যপ্রাচ্যেও হাসপাতাল রয়েছে। এর হাসপাতাল ও সার্জিক্যাল কেন্দ্র Pathadipalam, Changampuzha Nagar Post, Edappally-তে অবস্থিত, এবং সাশ্রয়ী দামে বিশ্বমানের স্বাস্থ্যসেবা প্রদানের লক্ষ্য রাখে। এটি NABH এবং Australian Council on Healthcare Standards International (ACHSI) দ্বারা স্বীকৃত।\n##specialities\nহাসপাতালটি বিভিন্ন রোগ ও অসুস্থতা কভার করে প্রায় ২৫টি বিভাগসহ ১২৫ শয্যার একটি মাল্টিস্পেশালিটি হাসপাতাল। এটি বহির্বিভাগ ও ভর্তি বিভাগ, ল্যাবরেটরি, ফার্মেসি, এক্স-রে, ECG এবং সার্বক্ষণিক পরিষেবা প্রদান করে, অভিজ্ঞ পরামর্শদাতা, প্রশিক্ষিত নার্স ও প্যারামেডিক্যাল কর্মীদের সহায়তায়।\n##technology\nহাসপাতালটি তার আকারের জন্য আধুনিক ও সুসজ্জিত। কোচির সবচেয়ে বড় হাসপাতালগুলোর তুলনায়, এটি একটি ছোট প্রতিষ্ঠান, তাই মাল্টি-অর্গান প্রতিস্থাপনের মতো অত্যন্ত জটিল চাহিদাসম্পন্ন রোগীদের অন্যত্র ভালো সেবা পাওয়া যেতে পারে।\n##international\nEdappally কোচির একটি ব্যস্ত এলাকা, Lulu Mall ও Edappally রেলওয়ে স্টেশনের কাছাকাছি। এর সুবিধাজনক অবস্থান ও মাঝারি আকার একে সাধারণ বা পরিকল্পিত প্রক্রিয়ার প্রয়োজন এমন রোগীদের জন্য একটি আরামদায়ক পরিবেশে উপযুক্ত করে তোলে।",
	'apollo-multispeciality-hospitals-kolkata':
		"##history\nকলকাতার Canal Circular Road-এ Apollo Multispeciality Hospitals, পূর্বে Apollo Gleneagles, ২০০৩ সালে প্রতিষ্ঠিত এবং ৭০০-৭৫০ শয্যার একটি টারশিয়ারি-কেয়ার হাসপাতাল। এটি পূর্ব ভারতের একমাত্র JCI-স্বীকৃত হাসপাতাল। এটি The Week–Hansa Research সমীক্ষা দ্বারা টানা ১২ বছর পূর্ব ও উত্তর-পূর্ব ভারতের নম্বর এক বেসরকারি হাসপাতাল হিসেবে নামকরণ করা হয়েছে, এবং ২০১৯ সালে Global Health and Travel Awards-এ পূর্ব ভারতের সেরা মাল্টিস্পেশালিটি হাসপাতাল পুরস্কার জিতেছে।\n##specialities\nহাসপাতালটিতে ৫০টিরও বেশি বিশেষত্ব এবং ৩৩টি উৎকর্ষ কেন্দ্র রয়েছে, হৃদযত্ন, ক্যান্সার যত্ন, অর্থোপেডিক্স, গ্যাস্ট্রোএন্টারোলজি, নিউরোসায়েন্স, প্রতিস্থাপন, রোবোটিক্স ও জরুরি যত্নসহ। এটি পূর্ব ভারতের প্রথম একযোগে হৃদয়, লিভার ও কিডনি প্রতিস্থাপন করেছে এবং অঞ্চলে সম্পূর্ণ রোবোটিক রেনাল প্রতিস্থাপন এনেছে, এবং Apollo গ্রুপ ১০,০০০-এরও বেশি কিডনি প্রতিস্থাপন করেছে। এটি আন্তর্জাতিক রোগীদের জন্য বোন ম্যারো প্রতিস্থাপনেও একটি বিশ্বস্ত নাম।\n##technology\nহাসপাতালটি প্রতিদিন ১,৬০০-এরও বেশি বহির্বিভাগ ভিজিট পরিচালনা করে এবং জীবিত-দাতা ও ক্যাডেভার সার্জারির জন্য সজ্জিত প্রতিস্থাপন কেন্দ্র রয়েছে।\n##international\nবছরে ১০,০০০-এরও বেশি আন্তর্জাতিক রোগী, অনেকে বাংলাদেশ থেকে, Apollo Kolkata-তে চিকিৎসা নেন, যেখানে একটি নিবেদিত আন্তর্জাতিক রোগী পরিষেবা দল রয়েছে। এটি কলকাতার Kankurgachi এলাকায় অবস্থিত।",
	'amri-hospitals-dhakuria':
		"##history\nAMRI Hospitals, Dhakuria, ১৯৯৬ সালে পশ্চিমবঙ্গ সরকারের সঙ্গে একটি সরকারি-বেসরকারি উদ্যোগ হিসেবে শুরু হয়, প্রথমে একটি বহির্বিভাগ সুবিধা হিসেবে, ১৯৯৭ সালে ১৫০ শয্যার হাসপাতালে বৃদ্ধি পেয়ে, পরে কয়েকশ শয্যায় সম্প্রসারিত হয়। Manipal Hospitals ২০২৩ সালে AMRI গ্রুপে একটি সংখ্যাগরিষ্ঠ অংশীদারিত্ব অর্জন করে, এবং Dhakuria হাসপাতালটি এখন Manipal Hospital Dhakuria (পূর্বে AMRI), Manipal Salt Lake, Dhakuria, Mukundapur ও Broadway-তে উপস্থিত থাকার সঙ্গে কলকাতায়। AMRI ব্র্যান্ডের অধীনে এটি ২০২০ ও ২০২১ সালে ABP News Healthcare Leadership Awards-এ পূর্ব ভারতের সেরা বেসরকারি হাসপাতাল নামকরণ করা হয়েছিল।\n##specialities\nহাসপাতালটি কার্ডিয়াক সায়েন্স, জয়েন্ট রিপ্লেসমেন্ট, ট্রমা যত্ন, IVF, ম্যাক্সিলোফেসিয়াল সার্জারি ও এস্থেটিক ও প্লাস্টিক সার্জারির জন্য পরিচিত। এর জরুরি ও ক্রিটিক্যাল কেয়ার পরিষেবা একটি উৎকর্ষ কেন্দ্র। ২০২৪ সালে এটি জরুরি যত্নে অবদান এবং নিউরোলজি ও স্ট্রোক ব্যবস্থাপনায় উৎকর্ষের জন্য Economic Times Healthcare Awards-এ পুরস্কার পেয়েছে, এবং বাংলাদেশি রোগীদের সেবার জন্য বাংলাদেশ সরকার কর্তৃক স্বীকৃত হয়েছে।\n##technology\nউন্নত নিউক্লিয়ার ইমেজিংয়ের মধ্যে রয়েছে PET-CT ও SPECT-CT, এবং রেডিওথেরাপির মধ্যে রয়েছে IMRT ও VMAT। হাসপাতালটি NABH দ্বারা স্বীকৃত। এটি South Kolkata-র Dhakuria-তে Gariahat Road-এ অবস্থিত।\n##international\nManipal Hospitals আন্তর্জাতিক রোগীদের জন্য নিবেদিত পরিষেবা প্রদান করে, মেডিক্যাল মতামত, চিকিৎসা পরিকল্পনা, ভ্রমণ সহায়তা ও ব্যক্তিগতকৃত সহায়তাসহ।",
	'fortis-hospital-anandapur':
		"##history\nকলকাতার Anandapur-এ ফোর্টিস হাসপাতাল ২০১১ সালে প্রতিষ্ঠিত হয় এবং Eastern Metropolitan Bypass-এ প্রায় সাত একর জুড়ে বিস্তৃত। এটি একটি ১০-তলা, প্রায় ৩০০ শয্যার প্রতিষ্ঠান, প্রায় ২৪০টি শয্যা সক্রিয়। মাইলফলকের মধ্যে রয়েছে পূর্ব ভারতের প্রথম কাস্টম-মেড নী রিপ্লেসমেন্ট (2011), পূর্ব ভারতের প্রথম জাগ্রত মস্তিষ্ক ক্র্যানিওটমি (2012), ভারতের প্রথম Heart Team চালু (2012) এবং ১২ কেজির কম ওজনের একটি শিশুর রেনাল প্রতিস্থাপন (2014)। এটি শহরের সেরা ট্রমা যত্ন মেডিক্যাল সুবিধার জন্য Times Bengal Icons 2023 উপাধি এবং CAHOCON 2024-এ পুরস্কার পেয়েছে।\n##specialities\nহাসপাতালটি কার্ডিওলজি ও হৃদ-সার্জারি, ইউরোলজি, নেফ্রোলজি, নিউরোসায়েন্স, অর্থোপেডিক্স, পরিপাক যত্ন, শ্বাসযন্ত্র চিকিৎসা, মা ও শিশু যত্ন, জরুরি পরিষেবা ও ক্রিটিক্যাল কেয়ারে বিশেষায়িত। এতে পালমোনারি হাইপারটেনশন, নন-ইনভেসিভ ভেন্টিলেশন ও অ্যালার্জির জন্য বিশেষজ্ঞ ক্লিনিকও রয়েছে, এবং অনকোলজি, ম্যাক্সিলোফেসিয়াল সার্জারি, ডেন্টিস্ট্রি, সাইকিয়াট্রি, ডায়াবেটোলজি, ডার্মাটোলজি ও ইএনটি প্রদান করে। এর কার্ডিয়াক কেন্দ্রে চারটি ক্যাথ ল্যাব, একটি কার্ডিয়াক OT, ১৪-শয্যার SICU এবং ২০-শয্যার CCU রয়েছে।\n##technology\nহাসপাতালটি NABH স্বীকৃতি ও NABL সার্টিফিকেশন ধারণ করে।\n##international\nফোর্টিস হেলথকেয়ারের অংশ হিসেবে, হাসপাতালটি গ্রুপের আন্তর্জাতিক রোগী পরিষেবার মাধ্যমে আন্তর্জাতিক রোগীদের সহায়তা করে। এটি EM Bypass-এ Anandapur-এ অবস্থিত, ব্যবসায়িক জেলা ও বিমানবন্দরের জন্য ভালোভাবে অবস্থিত।",
	'medica-superspecialty-hospital':
		"##history\nMukundapur-এ Medica Superspecialty Hospital ২০১০ সালে চালু হয় এবং পূর্ব ভারতের বৃহত্তম হাসপাতাল চেইন বলে বর্ণিত Medica গ্রুপের অংশ। এটি ১২৭ Eastern Metropolitan Bypass-এ ১৮টি বিভাগ ও আটটি উৎকর্ষ কেন্দ্রসহ কয়েকশ শয্যার একটি টারশিয়ারি-কেয়ার হাসপাতাল। ২০২২ সালের ফেব্রুয়ারিতে এটি চতুর্থ প্রজন্মের da Vinci রোবট স্থাপন করে, পূর্ব ভারতের প্রথম অফিসিয়াল রোবোটিক সার্জারি প্রশিক্ষণ কেন্দ্র হয়ে ওঠে। এটি পূর্ব ভারতের প্রথম সার্টিফাইড Green Operation Theatre-সহ হাসপাতাল, এবং ২০২৩ সালে Times Bengal Award পেয়েছে।\n##specialities\nহাসপাতালটি অ্যানেস্থেসিওলজি, কার্ডিওলজি, হৃদ-সার্জারি, ক্রিটিক্যাল কেয়ার, ডার্মাটোলজি, ডেন্টিস্ট্রি, জরুরি চিকিৎসা, এন্ডোক্রিনোলজি, ইএনটি, গ্যাস্ট্রোএন্টারোলজি, সাধারণ ও GI সার্জারি, হেমাটোলজি, লিভার রোগ, নেফ্রোলজি, নিউরোলজি, নিউরোসার্জারি, নিউরোটোলজি, নিউক্লিয়ার মেডিসিন, অর্থোপেডিক্স, প্রসূতি ও স্ত্রীরোগ, অনকোলজি, শিশু সার্জারি, প্লাস্টিক ও পুনর্গঠনমূলক সার্জারি, পুনর্বাসন, সাইকিয়াট্রি, রেডিওলজি, শ্বাসযন্ত্র চিকিৎসা, রিউমাটোলজি, রোবোটিক সার্জারি, ট্রান্সফিউশন মেডিসিন ও ইউরোলজি কভার করে।\n##technology\nMedica-তে অঞ্চলের সবচেয়ে উন্নত ক্রিটিক্যাল কেয়ার ইউনিটগুলোর একটি, একটি মলিকুলার ল্যাবসহ NABL-স্বীকৃত ল্যাবরেটরি এবং আন্তর্জাতিক মান পূরণকারী ইমেজিং পরিষেবা রয়েছে। এর ডায়ালাইসিস কেন্দ্র ২০২০ সালে স্বীকৃত হয় এবং সেরা ডায়ালাইসিস পরিষেবা প্রদানকারী পুরস্কার জিতেছে। হাসপাতালটি NABH ও NABL দ্বারা স্বীকৃত।\n##international\nMedica আন্তর্জাতিক রোগী পরিষেবা প্রদান করে এবং প্রতিবেশী দেশগুলোর রোগীদের জন্য একটি সুপরিচিত গন্তব্য।",
	'zydus-hospitals':
		"##history\nআহমেদাবাদের Zydus Hospitals Zydus Group-এর একটি উদ্যোগ, যা ২০১৫ সালে Sola Bridge-এর কাছে S. G. Highway-তে খোলে। এটি ১৬টি তলা ও দুটি বেসমেন্ট তলাসহ ৫৫০ শয্যার একটি সুপার-স্পেশালিটি হাসপাতাল, NABH ও NABL দ্বারা স্বীকৃত। এটি The Week–Marg সমীক্ষা দ্বারা চার বছর ধরে আহমেদাবাদের সেরা হাসপাতাল হিসেবে স্বীকৃত হয়েছে এবং গুজরাটের ১৮তম হাসপাতাল যা Global Green-OT পুরস্কার জিতেছে। হাসপাতালটি মার্কিন যুক্তরাষ্ট্র ও ইউরোপে প্রশিক্ষিত মেডিক্যাল বিশেষজ্ঞ নিয়োগ করেছে।\n##specialities\nZydus নিউরোলজি, গ্যাস্ট্রোইন্টেস্টাইনাল যত্ন, ইউরোলজি, স্ত্রীরোগ, অনকোলজি, মেরুদণ্ড, কসমেটিক ও প্লাস্টিক সার্জারি, নেফ্রোলজি ও ইএনটি-র একটি কেন্দ্র, IVF, জয়েন্ট রিপ্লেসমেন্ট, ক্যান্সার যত্ন, নিউরোলজি, হৃদ-সার্জারি, কিডনি প্রতিস্থাপন, লিভার প্রতিস্থাপন, নিউরোসার্জারি ও প্লাস্টিক সার্জারিতে উৎকর্ষ কেন্দ্রসহ। এর লিভার প্রতিস্থাপন কর্মসূচি ২০+ বিশেষজ্ঞের একটি বহু-শাখা দল দ্বারা সমর্থিত, এবং আহমেদাবাদ ও ভাদোদরায় এর কেন্দ্রগুলোতে ৪৩০+ কিডনি, ২৯৫+ লিভার ও ২২০+ বোন ম্যারো প্রতিস্থাপন করেছে।\n##technology\nহাসপাতালটি আধুনিক অপারেশন থিয়েটার, উন্নত ইমেজিং এবং বড় ক্রিটিক্যাল কেয়ার ক্ষমতাকে সবুজ বিল্ডিং অনুশীলনের সঙ্গে একত্রিত করে।\n##international\nআহমেদাবাদ পশ্চিম ভারতে একটি গুরুত্বপূর্ণ গন্তব্য হিসেবে আবির্ভূত হয়েছে, এবং Zydus ক্রমবর্ধমান আন্তর্জাতিক রোগীদের আকর্ষণ করে; এর ডাক্তাররা আফ্রিকান দেশ ও উজবেকিস্তানেও স্বাস্থ্য শিবির পরিচালনা করেন।",
	'cims-hospital':
		"##history\nCIMS হাসপাতাল, এখন Marengo Asia CIMS হাসপাতাল, ২০১০ সালে আহমেদাবাদের Sola-তে Science City Road-এর কাছে খোলে এবং Marengo Asia Hospitals গ্রুপের অংশ। এটি NABH, NABL ও JCI দ্বারা স্বীকৃত একটি মাল্টি-সুপার স্পেশালিটি সবুজ হাসপাতাল। ২০২৩ সালের অক্টোবরে, ড. ধীরেন শাহ পরিচালিত এর দল যা এশিয়ার প্রথম রক্তহীন হৃদ-প্রতিস্থাপন হিসেবে উপস্থাপন করে তা সম্পাদন করে, একটি লক্ষ্য-নির্দেশিত রক্তক্ষরণ ব্যবস্থাপনা প্রোটোকল ব্যবহার করে; রোগী সাধারণ ২১-২৪ দিনের তুলনায় নয় দিনে ছাড়পত্র পান।\n##specialities\nহাসপাতালটি ক্যান্সার যত্ন, কার্ডিয়াক সায়েন্স, গ্যাস্ট্রোএন্টারোলজি, লিভার প্রতিস্থাপন ও বিলিয়ারি সায়েন্স, অর্থোপেডিক্স ও জয়েন্ট রিপ্লেসমেন্ট, কিডনি বিজ্ঞান, নিউরোসায়েন্স, বোন ম্যারো প্রতিস্থাপন, বেরিয়াট্রিক সার্জারি, ক্লিনিক্যাল সাইকোলজি, রিউমাটোলজি, ডায়াবেটিক ফুট, ডেন্টাল ও ডার্মাটোলজি প্রদান করে। প্রতিস্থাপন কর্মসূচির পরিচালক এবং গুজরাটের প্রথম হৃদ-প্রতিস্থাপন সার্জন ড. ধীরেন শাহ-এর ১৬,০০০+ CABG সার্জারি এবং প্রায় ৫০টি হৃদ-প্রতিস্থাপন রয়েছে, এবং তিনি ভারতে ট্রান্স-অর্টিক TAVR ও হাইব্রিড CABG সম্পাদনকারী প্রথম ব্যক্তি ছিলেন। হাসপাতালটিতে হৃদয়, লিভার, কিডনি, ফুসফুস ও শিশু বোন ম্যারো প্রতিস্থাপনের জন্য একটি নিবেদিত প্রতিস্থাপন কেন্দ্র রয়েছে।\n##technology\nহাসপাতালটিকে Shukan Mall-এর বিপরীতে একটি ৩০০-৫০০ শয্যার প্রতিষ্ঠান হিসেবে বর্ণনা করা হয়, উন্নত ICU ও অপারেশন থিয়েটারসহ।\n##international\nহাসপাতালটি ভারত ও বিদেশের রোগীদের চিকিৎসা করে।",
	'sterling-hospital':
		"##history\nআহমেদাবাদের Gurukul, Memnagar-এ Sterling Hospitals ২০০১ সালে একটি টারশিয়ারি-কেয়ার হাসপাতাল হিসেবে প্রতিষ্ঠিত হয় এবং গুজরাট জুড়ে একটি হাসপাতাল নেটওয়ার্কে পরিণত হয়েছে। ২০০৯ সালে এটি গুজরাটের প্রথম হাসপাতাল যা সম্পূর্ণরূপে NABH দ্বারা স্বীকৃত হয়, এবং এর ল্যাবরেটরি গুজরাটের প্রথম যা NABL দ্বারা স্বীকৃত হয়। এটি IMRB ও The Week দ্বারা টানা তিন বছর (2007 থেকে 2009) সেরা হাসপাতাল নামকরণ করা হয়েছিল।\n##specialities\nSterling কার্ডিয়াক সায়েন্স, অনকোলজি (সার্জিক্যাল, মেডিক্যাল ও রেডিয়েশন), ক্রিটিক্যাল কেয়ার ও শ্বাসযন্ত্র চিকিৎসা, গ্যাস্ট্রোএন্টারোলজি ও GI সার্জারি, নিউরোসায়েন্স ও মেরুদণ্ড সার্জারি, নেফ্রোলজি ও ইউরোলজি, অর্থোপেডিক্স ও জয়েন্ট রিপ্লেসমেন্ট, প্রসূতি ও স্ত্রীরোগ, হেমাটোলজি, ট্রমা যত্ন, বেরিয়াট্রিক সার্জারি, ইএনটি ও অ্যানেস্থেসিওলজি প্রদান করে। এটি অঞ্চলের প্রথম লিভার প্রতিস্থাপন সম্পাদন করে, CRRT ডায়ালাইসিস চালু করে এবং গুজরাটের প্রথম বোন ম্যারো ইউনিট ও রাজ্যের বৃহত্তম ডায়ালাইসিস সুবিধা স্থাপন করে। এটি আহমেদাবাদে একটি শীর্ষস্থানীয় কার্ডিয়াক কেন্দ্র হিসেবে স্বীকৃত।\n##technology\nহাসপাতালটিতে প্রায় ৩০০টি শয্যা রয়েছে। এর শিশু ও নবজাতক ICU মাল্টি-প্যারামিটার মনিটরিং, ভেন্টিলেটর ও ECMO এবং উচ্চ নার্স-থেকে-রোগী অনুপাতসহ সজ্জিত।\n##international\nSterling প্রতি বছর ১৩০+ দেশ থেকে ২০,০০০-এরও বেশি আন্তর্জাতিক রোগীর চিকিৎসার কথা জানায়, একটি একক-স্টপ আন্তর্জাতিক রোগী পরিষেবার মাধ্যমে যা হাসপাতাল, ডাক্তার ও রোগীদের সমন্বয় করে।",
	'shalby-hospitals':
		"##history\nShalby Hospitals ১৯৯৪ সালে আহমেদাবাদে ড. বিক্রম আই. শাহ শুরু করা একটি জয়েন্ট রিপ্লেসমেন্ট কেন্দ্র হিসেবে শুরু হয়, এবং প্রায় ৩০ বছরে পশ্চিম, মধ্য ও উত্তর ভারত জুড়ে ভারতের দ্রুততম বর্ধনশীল মাল্টিস্পেশালিটি টারশিয়ারি হাসপাতাল চেইনগুলোর একটিতে পরিণত হয়েছে। আহমেদাবাদের প্রধান হাসপাতাল, Shalby Multispeciality Hospital, S. G. Highway-তে Ramdev Nagar, Satellite-এর কাছে অবস্থিত এবং ২০০৭ সালে প্রতিষ্ঠিত। ড. শাহ ১৯৯৩ সাল থেকে Shalby-র চেয়ারম্যান এবং তার জয়েন্ট রিপ্লেসমেন্ট কর্মসূচির প্রধান, এবং ২০০৩ সালে Dr. B. C. Roy International Award পেয়েছেন। ২০২৫ সালে গ্রুপটি Hurun India Healthcare Transformation and Medical Excellence Award এবং গুজরাটে মেডিক্যাল ট্যুরিজমের জন্য সেরা হাসপাতাল পুরস্কার পেয়েছে।\n##specialities\nShalby জয়েন্ট রিপ্লেসমেন্টের জন্য বিশ্বব্যাপী খ্যাতিমান, ১,৫০,০০০-এরও বেশি রিপ্লেসমেন্ট সম্পাদিত। ড. শাহ ও তার দল প্রতি মাসে ৮০০-এরও বেশি প্রাথমিক জয়েন্ট রিপ্লেসমেন্ট সম্পাদন করেন, এবং তার ZERO কৌশল নী রিপ্লেসমেন্টের সার্জিক্যাল সময় প্রায় ৮০ মিনিট থেকে প্রায় ১০-১২ মিনিটে কমিয়েছে। গ্রুপটি Rajiv Gandhi National Quality Award এবং FICCI পুরস্কারও পেয়েছে।\n##technology\nSG Highway হাসপাতালটি NABH ও NABL দ্বারা স্বীকৃত, প্রায় ২০০ শয্যাসহ।\n##international\nShalby-তে একটি বিশেষ আন্তর্জাতিক রোগী ডেস্ক রয়েছে যা ভিডিও পরামর্শ, ভ্রমণ ও ভিসা সহায়তা, থাকার সহায়তা এবং বিনামূল্যে বিমানবন্দর পিকআপ ও ড্রপ-অফ প্রদান করে।",
	'dr-agarwal-s-eye-hospital':
		"##history\nDr. Agarwal's Eye Hospital ১৯৫৭ সালে চেন্নাইতে পদ্ম ভূষণ ড. জয়বীর আগারওয়াল ও ড. তাহিরা আগারওয়াল প্রতিষ্ঠা করেন। ড. জয়বীর আগারওয়াল ২০০৬ সালের মার্চে পদ্ম ভূষণ পেয়েছেন। দশকের পর দশক ধরে এটি ভারতের অন্যতম বৃহত্তম চক্ষু-যত্ন চেইনে পরিণত হয়েছে, ১৪টি রাজ্য ও চারটি কেন্দ্রশাসিত অঞ্চলে এবং বিদেশে বেশ কয়েকটি দেশে, বিশেষত আফ্রিকায় কেন্দ্রসহ। কেন্দ্রের সঠিক সংখ্যা সূত্রভেদে পরিবর্তিত হয় এবং সময়ের সঙ্গে পরিবর্তিত হয়, তাই রোগীদের পরিকল্পনা করার সময় দিল্লি-NCR স্থানের বর্তমান তালিকা পরীক্ষা করা উচিত।\n##specialities\nহাসপাতালটি ব্যাপক চক্ষুবিদ্যা প্রদান করে, ফ্যাকোএমালসিফিকেশন ও ফেমটোসেকেন্ড লেজার সহায়তার মতো কৌশল ব্যবহার করে ছানি সার্জারি, LASIK ও অন্যান্য রিফ্র্যাক্টিভ সার্জারি, ডায়াবেটিক রেটিনোপ্যাথি ও রেটিনাল বিচ্ছিন্নতার মতো অবস্থার জন্য রেটিনা যত্ন, গ্লুকোমা, কর্নিয়া ও শিশু চক্ষুবিদ্যাসহ। গ্রুপটি সুপরিচিত চক্ষু সার্জন ও গবেষকদের সঙ্গেও যুক্ত, যার মধ্যে রয়েছেন ড. অমর আগারওয়াল, যিনি ছানি সার্জারিতে উদ্ভাবনের জন্য পরিচিত।\n##technology\nবেশিরভাগ চক্ষু প্রক্রিয়া ডে কেয়ার হিসেবে করা হয়, যা আন্তর্জাতিক দর্শনার্থীদের জন্য ব্যবহারিক করে তোলে। দিল্লি-NCR-এ বেশ কয়েকটি Dr. Agarwal's কেন্দ্র রয়েছে।\n##international\nযেহেতু অনেক চক্ষু প্রক্রিয়ার জন্য শুধুমাত্র একটি সংক্ষিপ্ত থাকার প্রয়োজন হয়, রোগীরা প্রায়ই অঞ্চলে ভ্রমণের সঙ্গে চিকিৎসা একত্রিত করতে পারেন।",
	'laimaa-fertility-ivf-surrogacy-clinic':
		"##history\nLaimaa Fertility ২০২২ সালে অভিজ্ঞ এমব্রায়োলজিস্ট ও ডাক্তারদের একটি দল প্রতিষ্ঠা করে এবং নয়াদিল্লির Greater Kailash Part II-এর E-580-এ অবস্থিত। এটি এমব্রায়োলজিস্ট পূজা আগারওয়াল, ড. আকাঙ্ক্ষা চৌহান ও ড. মমতা চাহারের নেতৃত্বে উদ্ভূত হয়, ড. বিনীত মালহোত্রাও দলে, চিকিৎসা ও ল্যাবরেটরি দক্ষতার সমন্বয়ে। এমব্রায়োলজিস্ট পূজা আগারওয়াল তার ক্যারিয়ার Fortis Ridge IVF Centre-এ শুরু করেন এবং গুরুগ্রাম ও নয়ডাসহ বেশ কয়েকটি প্রতিষ্ঠানে IVF ল্যাবরেটরি পরিচালনা করেছেন, এবং ভ্রূণ বায়োপসির জন্য একজন সার্টিফাইড এমব্রায়োলজিস্ট।\n##specialities\nক্লিনিকটি IVF, ICSI, IUI, ডিম্বাণু ও ভ্রূণ হিমায়িতকরণ, ডিম্বাণু দান, কাস্টমাইজড ওষুধ পরিকল্পনা, বন্ধ্যাত্বের জন্য মিনিমালি ইনভেসিভ সার্জিক্যাল প্রক্রিয়া এবং হরমোন থেরাপি প্রদান করে। এটি কম AMH ও গুরুতর পুরুষ-ফ্যাক্টর বন্ধ্যাত্বের মতো চ্যালেঞ্জিং কেসে কাজের জন্য পরিচিত, এবং এর এমব্রায়োলজি দল TESA-ICSI, PICSI, ব্লাস্টোসিস্ট স্থানান্তর এবং ডিম্বাণু ও ভ্রূণ হিমায়িতকরণ সম্পাদন করে। রোগীরা প্রায়ই ড. আকাঙ্ক্ষা চৌহানের দয়া, জ্ঞান ও উপলব্ধতার প্রশংসা করেন।\n##technology\nক্লিনিকটি উন্নত প্রজনন কৌশল ব্যবহার করে এবং ব্যক্তিগতকৃত যত্ন ও নৈতিক অনুশীলনের উপর জোর দেয়। একটি নতুন ক্লিনিক হিসেবে, এটি একটি ইন-হাউস এমব্রায়োলজি ল্যাবসহ একটি কেন্দ্রীভূত উর্বরতা কেন্দ্র হিসেবে কাজ করে।\n##international\nক্লিনিকটি ইংরেজি ও হিন্দিতে পরামর্শ প্রদান করে। Greater Kailash Part II হোটেল ও মেট্রো অ্যাক্সেসসহ South Delhi-র একটি সুসংযুক্ত এলাকা।",
	'gaudium-ivf':
		"##history\nGaudium IVF and Women Health ২০০৯ সালে ড. মণিকা খান্না প্রতিষ্ঠা করেন, একজন বিশ্বব্যাপী স্বীকৃত বন্ধ্যাত্ব বিশেষজ্ঞ ও ল্যাপারোস্কোপিক সার্জন, উর্বরতা চিকিৎসায় ২০+ বছরের অভিজ্ঞতাসহ। তিনি ২০০৮ সালে তৎকালীন ভারতের রাষ্ট্রপতির কাছ থেকে Delhi Ratan Award পেয়েছেন, এবং Rajiv Gandhi Excellence Award ও Women Achievers' Award-সহ পুরস্কার দিয়ে সম্মানিত হয়েছেন। Gaudium-এর এখন ছয়টি ভারতীয় রাজ্যে প্রায় ৩৬টি কেন্দ্র এবং অন্যান্য দেশে কেন্দ্র রয়েছে, এবং ৩০টিরও বেশি দেশে সুস্থ Gaudium শিশুদের কথা জানায়।\n##specialities\nকেন্দ্রটি IVF, ডিম্বাণু হিমায়িতকরণ ও ভ্রূণ হিমায়িতকরণ প্রদান করে, এবং বারবার IVF ব্যর্থতা, পুরুষ-ফ্যাক্টর বন্ধ্যাত্ব, এন্ডোমেট্রিওসিস ও উচ্চ-ঝুঁকিপূর্ণ গর্ভাবস্থার চিকিৎসার জন্য পরিচিত। ড. খান্না তার নামে ১০,০০০-এরও বেশি IVF চিকিৎসার কথা জানান, এবং গ্রুপের ক্লিনিকগুলোকে বহু-শাখা যত্ন ও অভিজ্ঞ এমব্রায়োলজিস্টসহ সুপার-স্পেশালিটি ক্লিনিক হিসেবে বর্ণনা করা হয়।\n##technology\nGaudium-এর এমব্রায়োলজি ইকোসিস্টেম AI-চালিত টুল ব্যবহার করে, শুক্রাণু মূল্যায়নের জন্য SiD ও ভ্রূণ মূল্যায়নের জন্য ERICA-সহ, এর Signature Lab কাঠামোর কেন্দ্রে, যা উন্নত এমব্রায়োলজিকে আন্তর্জাতিকভাবে বেঞ্চমার্ক করা মানের সঙ্গে একত্রিত করে। দিল্লি ক্লিনিকটি M-1, প্রথম তলায়, South Extension Part 2-তে অবস্থিত।\n##international\nGaudium ৩০টিরও বেশি দেশের দম্পতির চিকিৎসা করেছে। South Extension South Delhi-র একটি ব্যস্ত বাজার এলাকা, ভালো মেট্রো সংযোগসহ।",
	'pristyn-care-ferticity-super-speciality-ivf-hospital':
		"##history\nPristyn Care Ferticity Super Speciality & IVF হাসপাতাল ১২, Navjeevan Vihar, Geetanjali Enclave, Malviya Nagar, নয়াদিল্লিতে অবস্থিত, এবং বিশ্বজুড়ে ৪০,০০০-এরও বেশি পরিবারকে সাহায্য করার কথা জানায়। এর সহ-প্রতিষ্ঠাতা ও পরিচালক, ড. ইলা গুপ্তা, বন্ধ্যাত্ব চিকিৎসা ও সহায়ক প্রজনন প্রযুক্তিতে ২৯+ বছরের অভিজ্ঞতা রয়েছে, ৫,৫০০-এরও বেশি জটিল কেস পরিচালনা করেছেন, এবং ২০২৩ সালে Dr. APJ Abdul Kalam Health Award পেয়েছেন। ক্লিনিকটি ICMR ART Clinics Registry-তে তালিকাভুক্ত।\n##specialities\nহাসপাতালটি IVF, IUI, ICSI, ডিম্বাণু হিমায়িতকরণ, ভ্রূণ হিমায়িতকরণ এবং দাতা-ভিত্তিক চিকিৎসা খুঁজছেন এমন দম্পতিদের জন্য ডিজাইন করা হয়েছে। এটি PCOS, টিউবাল ব্লক, কম ওভারিয়ান রিজার্ভ, পুরুষ-ফ্যাক্টর বন্ধ্যাত্ব, এন্ডোমেট্রিওসিস ও বারবার গর্ভপাত পরিচালনা করে, এবং ডিম্বস্ফোটন ইন্ডাকশন ও বিস্তারিত হরমোনাল ও প্রজনন স্বাস্থ্য মূল্যায়ন প্রদান করে। ড. গুপ্তা প্লেটলেট-রিচ প্লাজমা থেরাপি ও জেনেটিক স্ক্রিনিংয়ের মতো কৌশল ব্যবহার করে ৭৮% পর্যন্ত সাফল্যের হারের কথা জানান, যদিও ফলাফল রোগীভেদে পরিবর্তিত হয়।\n##technology\nসমস্ত উর্বরতা বিশেষজ্ঞ মেডিক্যাল কাউন্সিলে নিবন্ধিত, এবং ক্লিনিকটি অপারেটিং সুবিধা, এমব্রায়োলজি ল্যাবরেটরি ও কাউন্সেলিং সহায়তাসহ একটি সুপার-স্পেশালিটি ও IVF হাসপাতাল হিসেবে পরিচালিত হয়। এটি সোমবার থেকে শনিবার খোলা থাকে।\n##international\nক্লিনিকটি আন্তর্জাতিক দম্পতির চিকিৎসা করেছে, যার মধ্যে ড. গুপ্তার সঙ্গে IVF-এর জন্য যুক্তরাষ্ট্র থেকে ভ্রমণকারী রোগীরাও রয়েছেন। Malviya Nagar South Delhi-র Malviya Nagar মেট্রো স্টেশনের কাছে।",
	'nova-ivf-fertility-centre-rajouri-garden':
		"##history\nRajouri Garden-এ Nova IVF Fertility কেন্দ্র দিল্লির গ্রুপের ক্লিনিকগুলোর একটি, Rajouri Garden মেট্রোর কাছে GN-14, Shivaji Enclave, Sector G, Mehta Chowk-এ। Nova IVF Fertility ১১ সালে প্রতিষ্ঠিত হয়, এবং গ্রুপটি ২০২১ সালে ET Healthworld National Fertility Awards-এ Best IVF Chain in India পুরস্কার এবং ২০২৫ সালে IVF/Fertility Champion of the Year পুরস্কার পেয়েছে। গ্রুপটি তার নেটওয়ার্কে ৮৫,০০০-১,০০,০০০+ IVF জীবিত জন্মের কথা জানায়।\n##specialities\nক্লিনিকটি IUI, IVF, ICSI ও MACS স্পার্ম সিলেকশন, ডিম্বাণু হিমায়িতকরণ, দাতা কর্মসূচি ও উন্নত ডায়াগনস্টিকস প্রদান করে, এবং পুরুষ বন্ধ্যাত্ব, অব্যাখ্যাত বন্ধ্যাত্ব, কম ওভারিয়ান রিজার্ভ, PCOS, এন্ডোমেট্রিওসিস ও টিউবাল-ফ্যাক্টর বন্ধ্যাত্বের চিকিৎসা করে। ড. অস্বতী নায়ার একজন IVF বিশেষজ্ঞ যিনি মুম্বাইতে তার MBBS সম্পন্ন করেছেন এবং প্রসূতি ও স্ত্রীরোগে MD, তারপর প্রজনন ঔষধে FNB, ১৭+ বছরের অভিজ্ঞতাসহ। তিনি বারবার ইমপ্লান্টেশন ব্যর্থতায় ভ্রূণ আঠার উপর গবেষণার জন্য ISAR কেরালা শাখায় সেরা পেপার পুরস্কার জিতেছেন। ড. মীনাক্ষী ব্যানার্জি, ২০+ বছরের অভিজ্ঞতাসম্পন্ন একজন স্ত্রীরোগ বিশেষজ্ঞ, এখানেও অনুশীলন করেন।\n##technology\nদিল্লি NCR-এর অন্যান্য Nova IVF ক্লিনিকের মতো, এতে একটি উন্নত এমব্রায়োলজি ল্যাবরেটরি, আধুনিক অপারেশন থিয়েটার ও আরামদায়ক পুনরুদ্ধার এলাকা রয়েছে, আন্তর্জাতিক প্রোটোকল অনুসরণ করে। ক্লিনিকটি সোমবার থেকে শনিবার খোলা থাকে।\n##international\nRajouri Garden মেট্রো দিয়ে কেন্দ্রীয় দিল্লি ও বিমানবন্দর লাইনের সঙ্গে ভালোভাবে সংযুক্ত।",
	'elixir-fertility-centre':
		"##history\nElixir Fertility Centre ২০১৪ সালে প্রতিষ্ঠিত হয় এবং উত্তর দিল্লিতে Vardhman Royal Plaza, Plot 5, LSC Gujranwala Town-1-এ একটি IVF ও উর্বরতা ক্লিনিক। এর লক্ষ্য অভিজ্ঞ বন্ধ্যাত্ব বিশেষজ্ঞদের উন্নত প্রযুক্তির সঙ্গে একত্রিত করে সাফল্যের হার বাড়ানো, এবং এর IVF বিশেষজ্ঞ ও এমব্রায়োলজিস্টরা যুক্তরাজ্য, জার্মানি, সিঙ্গাপুর ও ভারতের শীর্ষস্থানীয় কেন্দ্রে প্রশিক্ষণ নিয়েছেন।\n##specialities\nকেন্দ্রটি IVF, ICSI, IUI, সিমেন বিশ্লেষণ ও জেনেটিক স্ক্রিনিং প্রদান করে। এর দলে রয়েছেন ড. পুনীত কোছার, একজন IVF বিশেষজ্ঞ যিনি পূর্বে যুক্তরাজ্যের কেমব্রিজের Bourn Hall Clinic-এ কাজ করেছেন এবং দিল্লির Lady Hardinge Medical College-এ পড়িয়েছেন; ড. প্রণয় ঘোষ, পরিচালক ও উর্বরতা পরামর্শদাতা, যিনি নটিংহামের NURTURE, সিঙ্গাপুরের NUH CREST এবং কিয়েলের Centre of Reproductive Medicine-সহ কেন্দ্রে প্রশিক্ষণ নিয়েছেন এবং সম্মানসহ যুক্তরাজ্যে মাস্টার্স সম্পন্ন করেছেন; ড. রাজীব সিংলা, একজন প্রজনন এন্ডোক্রিনোলজিস্ট; এবং ড. তেইতা ঘোষ, একজন ক্লিনিক্যাল জেনেটিসিস্ট ও প্রজনন ইমিউনোলজিস্ট।\n##technology\nক্লিনিকটিতে একটি ডায়াগনস্টিক ল্যাবরেটরি, আল্ট্রাসাউন্ড, জরুরি পরিষেবা ও পার্কিং রয়েছে, এবং সোমবার থেকে শনিবার সকাল ৯টা থেকে সন্ধ্যা ৬টার মধ্যে কাজ করে। এটি ৬৫-৭৫% পরিসরে IVF সাফল্যের হারের কথা জানায়, যা ব্যক্তিগত পরিস্থিতি অনুযায়ী পরিবর্তিত হবে।\n##international\nউত্তর দিল্লির Gujranwala Town Model Town ও Kamla Nagar-এর কাছাকাছি এবং কেন্দ্রীয় দিল্লি থেকে মেট্রো দিয়ে পৌঁছানো যায়।",
	'femmenest-fertility-ivf-centre':
		"##history\nFemmenest পূর্ব দিল্লিতে একটি প্রিমিয়াম নারী স্বাস্থ্য কেন্দ্র যা IVF, বন্ধ্যাত্ব ও স্ত্রীরোগ পরিষেবা প্রদান করে, C-52 UGF, Anand Vihar-এ, Pushpanjali Medical Centre-এর বিপরীতে। কেন্দ্রটির নেতৃত্বে রয়েছেন ড. সৌজন্যা আগারওয়াল, একজন IVF বিশেষজ্ঞ ও স্ত্রীরোগ ল্যাপারোস্কোপিক ও রোবোটিক সার্জন, ২০+ বছরের ক্লিনিক্যাল অভিজ্ঞতাসহ। তিনি চেন্নাইয়ের Sri Ramachandra University-তে প্রসূতি ও স্ত্রীরোগে MS সম্পন্ন করেন, তারপর কোচিতে মিনিমাল অ্যাক্সেস স্ত্রীরোগ সার্জারি ও প্রজনন ঔষধে ফেলোশিপ করেন, এবং ২০১২ সালে Dr. Jagdishwari Mishra Oration Award পেয়েছেন।\n##specialities\nকেন্দ্রটি IVF, IUI ও ICSI, দম্পতিদের জন্য ব্যক্তিগতকৃত সহায়তা, রোগনির্ণয় থেকে হরমোনাল থেরাপি পর্যন্ত সম্পূর্ণ বন্ধ্যাত্ব যত্ন, এবং PCOS, হরমোনাল ভারসাম্যহীনতা, উর্বরতা উদ্বেগ ও নিয়মিত নারী স্বাস্থ্য পরীক্ষার জন্য উন্নত স্ত্রীরোগ যত্ন প্রদান করে, ফিটাল মেডিসিনসহ। এতে সিনিয়র ডাক্তার, ক্লিনিক্যাল এমব্রায়োলজিস্ট, সহায়ক কর্মী ও নিবেদিত নার্সের একটি দল রয়েছে।\n##technology\nকেন্দ্রটি সম্পূর্ণ নারী যত্নের জন্য অত্যাধুনিক সুবিধা দিয়ে সজ্জিত। এটি সাধারণত সোমবার থেকে শনিবার সকাল ৯টা থেকে রাত ৮টা এবং রবিবার সকালে খোলা থাকে, এবং রোগীদের দ্বারা অত্যন্ত উচ্চ রেটিং পায়।\n##international\nAnand Vihar মেট্রো এবং Anand Vihar রেলওয়ে টার্মিনাস ও বাস টার্মিনাস দিয়ে ভালোভাবে সংযুক্ত, যা অন্যান্য শহর থেকে আসা ভ্রমণকারীদের জন্য সুবিধাজনক।",
	'india-ivf-clinic':
		"##history\nVasant Vihar-এ India IVF Clinic ফোর্টিস নেটওয়ার্কের একটি উর্বরতা ক্লিনিক। এটি Vasant Kunj-এর Fortis Flt. Lt. Rajan Dhall Hospital-এ পরামর্শ উপস্থিতি নিয়ে অনুশীলন করে, এবং 35, Second Floor, Community Centre, Basant Lok, Vasant Vihar ঠিকানায় তালিকাভুক্ত। এটি প্রায় ১২ বছর ধরে স্বাস্থ্যসেবায় রয়েছে এবং রোগীদের দ্বারা অত্যন্ত উচ্চ রেটিং পায়।\n##specialities\nড. রিচিকা সাহায় উর্বরতা দল পরিচালনা করেন। তার ২০+ বছরের অভিজ্ঞতা রয়েছে একজন উর্বরতা বিশেষজ্ঞ ও স্ত্রীরোগ ল্যাপারোস্কোপিক সার্জন হিসেবে, একজন সার্টিফাইড প্রজনন এন্ডোক্রিনোলজিস্ট ও বন্ধ্যাত্ব (IVF-ICSI) উপ-বিশেষজ্ঞ, স্বর্ণপদকসহ মেডিক্যাল স্কুল থেকে স্নাতক এবং ২০১৮ সালে Best Young IVF Specialist পুরস্কার পেয়েছেন। তার দক্ষতার ক্ষেত্রগুলোর মধ্যে রয়েছে IVF ও ICSI, ডিম্বাণু ও ভ্রূণ হিমায়িতকরণ, ডিম্বস্ফোটন ইন্ডাকশন, IUI, প্রি-ইমপ্লান্টেশন জেনেটিক টেস্টিং ও স্ক্রিনিং, এবং গর্ভধারণ ও গর্ভপাত ব্যবস্থাপনা। তিনি পুষ্টি, জীবনধারা ও পরিবেশের প্রতি মনোযোগ দিয়ে একটি সামগ্রিক পদ্ধতি গ্রহণ করেন।\n##technology\nক্লিনিকটি হুইলচেয়ার অ্যাক্সেসযোগ্য এবং পার্কিংসহ। রোগীরা কর্মীদের বন্ধুত্বপূর্ণ, যত্নশীল ও সহায়ক বলে বর্ণনা করেন, সফল গর্ভাবস্থা ও জন্মের কথা উল্লেখ করেন।\n##international\nযেহেতু দলটি আন্তর্জাতিক বিমানবন্দরের কাছে Fortis Vasant Kunj-এও কাজ করে, আন্তর্জাতিক দম্পতিরা একটি সুসজ্জিত মাল্টিস্পেশালিটি হাসপাতালের সঙ্গে উর্বরতা পরামর্শ একত্রিত করতে পারেন।",
	'spruce-dental':
		"##history\nSouth Delhi-র Jasola Vihar-এ Spruce Dental ইমপ্ল্যান্টোলজিস্ট ও অর্থোডন্টিস্ট ড. জাভেদ রিজওয়ান পরিচালিত Spruce Dental গ্রুপ ক্লিনিকের অংশ এবং একটি ISO 9001:2015 সার্টিফাইড ক্লিনিক। এটি 122, Pocket 2, Jasola-তে, DAV স্কুলের কাছে অবস্থিত এবং রোগীদের দ্বারা ভালো রেটিং পায়। ড. রিজওয়ান BDS ও MDS ধারণ করেন এবং জার্মানিতে কৌশলগত ইমপ্ল্যান্টোলজিতে মাস্টার্স করেছেন, যেখানে তিনি মিউনিখে কর্টিকোবেসাল ইমপ্ল্যান্টোলজির একজন অগ্রদূতের কাছে প্রশিক্ষণ নিয়েছেন। তার ১৫,০০০+ ইমপ্ল্যান্ট এবং ৫০০-এরও বেশি সম্পূর্ণ মুখের তাৎক্ষণিক ইমপ্ল্যান্ট কেস রয়েছে।\n##specialities\nক্লিনিকটি ক্ষতিগ্রস্ত দাঁত রক্ষার জন্য ব্যথাহীন রুট ক্যানাল থেরাপি, অনুপস্থিত দাঁতের জন্য সম্পূর্ণ মুখের ডেন্টাল ইমপ্ল্যান্ট, একক দাঁত ইমপ্ল্যান্ট, পেশাদার দাঁত সাদা করা, উন্নত অর্থোডন্টিক বিকল্প এবং কসমেটিক ডেন্টিস্ট্রির সঙ্গে স্মাইল মেকওভার প্রদান করে। গ্রুপটি সাধারণ ডেন্টিস্ট্রি ও ইমপ্ল্যান্টোলজিতে ক্লিনিক্যাল রেসিডেন্সি প্রোগ্রাম পরিচালনা করে।\n##technology\nডিজিটাল ইমেজিং দাঁত ও মাড়ির স্পষ্ট দৃশ্য দেয় ভালো চিকিৎসা পরিকল্পনার জন্য, এবং ক্লিনিকটি একটি আরামদায়ক পরিবেশে নৈতিক, রোগী-প্রথম দাঁতের যত্ন প্রদানের লক্ষ্য রাখে।\n##international\nJasola Vihar South Delhi-র Indraprastha Apollo Hospital ও Jasola মেট্রো স্টেশনের কাছাকাছি। ডেন্টাল ইমপ্ল্যান্ট ও স্মাইল-ডিজাইন কাজ প্রায়ই অল্প কয়েকটি ভিজিটে পরিকল্পনা করা হয়।",
	'zemya-ivf-fertility-clinics':
		"##history\nZemya IVF & Fertility Clinics নয়াদিল্লির C-10, Green Park Extension-এ একটি উর্বরতা কেন্দ্র, যা দিল্লি NCR-এর শীর্ষস্থানীয় IVF কেন্দ্রগুলোর একটি হিসেবে বর্ণিত। এটি সহানুভূতিশীল, রোগী-কেন্দ্রিক যত্ন প্রদান করে এবং ৫০,০০০-এরও বেশি দম্পতিকে সাহায্য করার কথা জানায়। এর দলে রয়েছেন বিশ্বব্যাপী প্রশিক্ষিত IVF বিশেষজ্ঞ ও ESHRE-সার্টিফাইড এমব্রায়োলজিস্ট, ক্লিনিক্যাল এমব্রায়োলজি ও সহায়ক প্রজনন প্রযুক্তিতে ১৫+ বছরের অভিজ্ঞতাসম্পন্ন একজন সিনিয়র এমব্রায়োলজিস্ট ও IVF ল্যাব ম্যানেজারসহ।\n##specialities\nZemya এক ছাদের নিচে IVF, ICSI ও IUI, পুরুষ বন্ধ্যাত্ব যত্ন, ডিম্বাণু হিমায়িতকরণ ও উর্বরতা সংরক্ষণ প্রদান করে, ব্যক্তিগতকৃত চিকিৎসা পরিকল্পনাসহ। এর চিকিৎসা পাতাগুলো IVF, ICSI ও পুরুষ বন্ধ্যাত্ব বিস্তারিতভাবে কভার করে।\n##technology\nসুবিধাগুলোর মধ্যে রয়েছে প্রশস্ত অপেক্ষার ঘর, প্রাইভেট ও বিলাসবহুল পুনরুদ্ধার কক্ষ, মডুলার অপারেশন থিয়েটার, একটি আধুনিক IVF ল্যাবরেটরি, পুরুষ উর্বরতা পরীক্ষার জন্য একটি উন্নত অ্যান্ড্রোলজি ল্যাবরেটরি, নিজস্ব ফার্মেসি, একটি প্যাথলজি ল্যাবরেটরি, একটি আন্তর্জাতিক রোগী লাউঞ্জ, একটি কাউন্সেলিং রুম, একটি কনফারেন্স রুম এবং ভিডিও পরামর্শ পরিষেবা।\n##international\nGreen Park মেট্রো অ্যাক্সেস, হোটেল ও রেস্তোরাঁসহ South Delhi-র একটি সুসংযুক্ত এলাকা, এবং ক্লিনিকটিতে আন্তর্জাতিক রোগীদের জন্য একটি লাউঞ্জ রয়েছে।",
	'kokilaben-dhirubhai-ambani-hospital':
		"##history\nAndheri West (মুম্বাই)-এ Rao Saheb Achutrao Patwardhan Marg-এ Kokilaben Dhirubhai Ambani হাসপাতাল ২০০৯ সালের শুরুতে ৭৫০ শয্যার একটি মাল্টিস্পেশালিটি হাসপাতাল হিসেবে কার্যকর হয়। এটি মুম্বাই, প্রতিবেশী অঞ্চল ও আন্তর্জাতিক রোগীদের সেবা দেয় এবং JCI, NABH ও CAP দ্বারা স্বীকৃত। ২০২৫ সালে এটি Financial Express Healthcare Summit and Awards-এ ছয়টি বিভাগে (মাল্টিস্পেশালিটি, অনকোলজি, রোবোটিক্স, নিউরোলজি, অর্থোপেডিক্স ও পুনর্বাসন) Best Hospital – National নামকরণ করা হয়, এবং NABH Digital Health Excellence Award পেয়েছে।\n##specialities\nহাসপাতালটি ২১,০০০-এরও বেশি জটিল ক্যান্সার সার্জারি, ২৮০-এরও বেশি লিভার প্রতিস্থাপন এবং ৩,৬০০-এরও বেশি রোবোটিক সার্জারির কথা জানায়, ৪০০+ ডাক্তারের একটি দল দ্বারা সম্পাদিত। ২০১২ সালে স্থাপিত এর Centre for Robotic Surgery-কে চালুর ৪৮ মাসের মধ্যে ১,০০০ রোবোটিক সার্জারিতে পৌঁছানো সবচেয়ে দ্রুততম হিসেবে বর্ণনা করা হয়। অনকোলজি, নিউরোসায়েন্স, অর্থোপেডিক্স, কার্ডিয়াক সায়েন্স, প্রতিস্থাপন ও পুনর্বাসন এর প্রধান শক্তিগুলোর মধ্যে রয়েছে।\n##technology\nহাসপাতালটিতে প্রায় ১৮০টি ICU শয্যা রয়েছে এবং এটি বেশ কয়েকটি প্রথমের স্থান ছিল, যার মধ্যে রয়েছে এশিয়ার প্রথম তিন-কক্ষের ইন্ট্রা-অপারেটিভ MRI স্যুট (IMRIS), Varian-এর এশিয়ার প্রথম EDGE রেডিওসার্জারি সিস্টেম এবং O-arm-সহ ভারতের প্রথম মেরুদণ্ড সার্জারি স্যুট। এটি da Vinci Xi এবং ভারতের প্রথম Toumai রোবোটিক সার্জারি সিস্টেম ব্যবহার করে, যা 3D HD ভিজুয়ালাইজেশন ও টেলিসার্জারি সক্ষমতা প্রদান করে।\n##international\nKokilaben তার আন্তর্জাতিক রোগী যত্নের জন্য পরিচিত, কনসিয়ার্জ পরিষেবা এবং সমস্ত মেডিক্যাল ভ্রমণ প্রয়োজনে সহায়তাসহ। Andheri West মেট্রো ও মুম্বাইয়ের আন্তর্জাতিক বিমানবন্দরের কাছাকাছি।",
	'p-d-hinduja-hospital':
		"##history\nP. D. Hinduja হাসপাতাল ১৯৫১ সালে Parmanand Deepchand Hinduja প্রতিষ্ঠা করেন Massachusetts General Hospital-এর সহযোগিতায়, Harvard Medical School-এর প্রধান শিক্ষাদান হাসপাতাল, এবং ১৯৬৩ সালে Mahim সাইটে তার East Wing বিল্ডিংয়ে স্থানান্তরিত হয়, একটি সাধারণ বহির্বিভাগ সুবিধা থেকে একটি সম্পূর্ণ হাসপাতালে রূপান্তরিত হয়। এটি Veer Savarkar Marg-এ, Shivaji Park-এর কাছে অবস্থিত। এটি Bureau Veritas থেকে Green and Clean Hospital Platinum Certificate পাওয়া ভারতের প্রথম হাসপাতাল হয়ে ওঠে, এবং স্বাস্থ্যসেবার মানের জন্য IMC Ramkrishna Bajaj National Award-সহ পুরস্কার জিতেছে।\n##specialities\nহাসপাতালটি প্রসূতিবিদ্যা ছাড়া ৪৫টিরও বেশি বিশেষত্বে পরিষেবা প্রদান করে, ৫৩টি ক্রিটিক্যাল কেয়ার শয্যা, ১৯টি ডে-কেয়ার ইউনিট, ১৭০ জন পরামর্শদাতা এবং ৮০০-এরও বেশি নার্স ও অন্যান্য কর্মীসহ, একটি স্বাস্থ্য স্ক্রিনিং কেন্দ্রসহ। এটি মুম্বাইয়ের প্রথম বেসরকারি হাসপাতাল যা একটি ক্যাডেভার কিডনি প্রতিস্থাপন ও একটি পেরিফেরাল ব্লাড স্টেম সেল প্রতিস্থাপন সম্পাদন করে, এবং ভারতের প্রথম হাসপাতাল যা মৃগীরোগ সার্জারির জন্য জাগ্রত ক্র্যানিওটমি সম্পাদন করে। কার্ডিওলজি, অনকোলজি, নিউরোলজি ও অর্থোপেডিক্স এর প্রধান শক্তিগুলোর মধ্যে রয়েছে।\n##technology\nহাসপাতালটি ২৬টি বিশেষত্বে DNB কোর্স, MSc ও PhD প্রোগ্রাম, একটি নার্সিং কলেজ ও অ্যালাইড হেলথ কোর্স পরিচালনা করে, এবং Hôpitaux Universitaires de Genève, Stanford University ও Henry Ford Health-এর মতো প্রতিষ্ঠানের সঙ্গে সহযোগিতা করে। এটি NABH দ্বারা স্বীকৃত।\n##international\nহাসপাতালটিতে চিকিৎসা পরিকল্পনা ও সমন্বয় করতে সাহায্য করার জন্য একটি নিবেদিত আন্তর্জাতিক রোগী পরিষেবা বিভাগ রয়েছে। Mahim রেল ও সড়ক দ্বারা কেন্দ্রীয় মুম্বাই ও বিমানবন্দরের সঙ্গে ভালোভাবে সংযুক্ত।",
	'fortis-hospital-mulund':
		"##history\nফোর্টিস হাসপাতাল, Mulund, ২০০২ সালে খোলে এবং Mulund–Goregaon Link Road-এ ৪০০ শয্যার একটি কোয়াটারনারি-কেয়ার মাল্টিস্পেশালিটি হাসপাতাল। এটি ভারত ও দক্ষিণ এশিয়ার প্রথম হাসপাতাল হিসেবে বর্ণিত যা JCI স্বীকৃতি পায়, এবং পশ্চিম ভারতের একমাত্র হাসপাতাল যার সাতটি টানা JCI স্বীকৃতি রয়েছে। এটি দেশের প্রথম হাসপাতাল যা জরুরি পরিষেবার জন্য NABH স্বীকৃতি পায় এবং ভারতের প্রথম হাসপাতাল যা একটি ইলেকট্রনিক ICU চালু করে। হাসপাতালটি স্বাস্থ্যসেবা উৎকর্ষের জন্য ২৫০+ পুরস্কার অর্জন করেছে।\n##specialities\nফোর্টিস Mulund মহারাষ্ট্রের বৃহত্তম মাল্টি-অর্গান প্রতিস্থাপন কেন্দ্রের আবাসস্থল, কিডনি, লিভার, হৃদয় ও বোন ম্যারো কভার করে। এটি পশ্চিম ভারতে মাত্র চার বছরে ১০০+ হৃদ-প্রতিস্থাপন সম্পন্নকারী প্রথম হাসপাতাল ছিল এবং ২০২৪ সালে তার ১০০তম বোন ম্যারো প্রতিস্থাপন সম্পন্ন করে। এর নিউরোসায়েন্স কর্মসূচি, উন্নত নিউরো-ইমেজিং ও নিউরো-ক্রিটিক্যাল কেয়ার ইউনিটসহ, ভারতের অন্যতম সেরা বলে বিবেচিত হয়, এবং এটি কার্ডিয়াক সায়েন্স, অনকোলজি, নেফ্রোলজি, ইউরোলজি, অর্থোপেডিক্স, গ্যাস্ট্রোএন্টারোলজি, জরুরি ও ক্রিটিক্যাল কেয়ার এবং মাতৃত্বকালীন যত্নও প্রদান করে।\n##technology\nহাসপাতালটিতে ১০৮টি ICU শয্যা, ছয়টি নিবেদিত বোন ম্যারো প্রতিস্থাপন ইউনিট এবং একটি লেভেল ১ ট্রমা কেন্দ্র রয়েছে। অনকোলজি Versa HD লিনিয়ার এক্সিলারেটর ব্যবহার করে, এবং হাসপাতালটি এই রেডিয়েশন প্ল্যাটফর্মসহ দেশের কয়েকটি প্রতিষ্ঠানের একটি।\n##international\nফোর্টিস Mulund একটি ২৪/৭ International Patient Unit পরিচালনা করে যা পুরো চিকিৎসা প্রক্রিয়া জুড়ে রোগী ও পরিবারকে সহায়তা করে। এটি মুম্বাইয়ের পূর্ব শহরতলিতে, Mulund রেলওয়ে স্টেশনের কাছাকাছি অবস্থিত।",
	'jaslok-hospital':
		"##history\nJaslok Hospital & Research Centre, Peddar Road-এ Dr. G. Deshmukh Marg-এ, প্রতিষ্ঠা করেন জনহিতৈষী Seth Lokoomal Chanrai এবং সার্জন Shantilal Jamnadas Mehta, এবং ১৯৭৩ সালের ৬ জুলাই প্রধানমন্ত্রী ইন্দিরা গান্ধী উদ্বোধন করেন। এটি ভারতের অন্যতম পুরনো টারশিয়ারি-কেয়ার মাল্টিস্পেশালিটি ট্রাস্ট হাসপাতাল, এবং ২০২২ সালে Navbharat Healthcare Award দিয়ে ৫০ বছরের সেবা উদযাপন করেছে।\n##specialities\nহাসপাতালটিতে প্রায় ৫০টি বিশেষত্ব এবং প্রায় ২০টি স্পেশালিটি ক্লিনিক রয়েছে, ৩৫০+ শয্যাসহ 75+ ICU শয্যা। এটি ১৯৭৪ সালে ভারতের একটি বেসরকারি হাসপাতালে প্রথম রেনাল প্রতিস্থাপন সম্পন্ন করে, ভারতের প্রথম বেসরকারি ইউরোলজি বিভাগ চালু করে, এবং ১৯৯৮ সালে মুম্বাইয়ের প্রথম বেসরকারি লিভার প্রতিস্থাপন ও পশ্চিম ভারতের প্রথম শিশু লিভার প্রতিস্থাপন অর্জন করে। এটি ভারতের প্রথম ট্রিপল-হেড গামা ক্যামেরা ও সলিড-স্টেট কার্ডিয়াক ক্যামেরা চালু করে, এবং 2D ইকোকার্ডিওগ্রাফি, ইলেক্ট্রোফিজিওলজি ও ড্রাগ-এলুটিং স্টেন্টসহ মুম্বাইয়ের প্রথম হিসেবে। প্রজনন ঔষধে এটি IVF-এ বিশ্বের প্রথম Cumulus Aided Transfer-এর কথা জানায়, এবং ২০১৯ সালে ET Healthcare Fertility Awards-এ Best IVF Clinic পুরস্কার জিতেছে।\n##technology\nহাসপাতালটি NABH (৫ম সংস্করণ), NABL দ্বারা স্বীকৃত এবং ISO 9001, 14001 ও 45001 সার্টিফিকেশন ধারণ করে, NABH নার্সিং এক্সেলেন্স ও এথিক্স কমিটি স্বীকৃতিসহ।\n##international\nJaslok আন্তর্জাতিক রোগীদের সহায়তা প্রদান করে, টেলিকনসালটেশন ও বিস্তারিত চিকিৎসা পরিকল্পনাসহ আগমনের আগে পরামর্শ ও খরচ পরিকল্পনা, এবং ভিসা ও ভ্রমণ সহায়তা। এটি Mahalaxmi-র কাছে দক্ষিণ মুম্বাইতে অবস্থিত।",
	'nanavati-max-super-speciality-hospital':
		"##history\nVile Parle-তে Nanavati Max Super Speciality হাসপাতাল ১৯৫০ সালের নভেম্বরে ভারতের প্রথম প্রধানমন্ত্রী জওহরলাল নেহেরু উদ্বোধন করেন, মহাত্মা গান্ধী কর্তৃক আশীর্বাদপ্রাপ্ত, এবং ১৯৫১ সালে রোগীদের জন্য খোলে। এটি ৭০+ বছর ধরে মুম্বাইয়ের স্বাস্থ্যসেবার একটি স্তম্ভ, এবং এখন Max Healthcare-এর অংশ। এতে ৩৫০টি শয্যা, ৩৫০+ পরামর্শদাতা, ১০০+ আবাসিক ডাক্তার, প্রায় ৪৭৫ জন নার্সিং কর্মী এবং প্রায় ১,৫০০ জন কর্মচারী রয়েছেন।\n##specialities\nহাসপাতালটিতে ৫৫টি বিশেষত্ব বিভাগ এবং কার্ডিওলজি, অনকোলজি, নেফ্রোলজি, অর্থোপেডিক্স, মেরুদণ্ড সার্জারি, নিউরোলজি, বেরিয়াট্রিক্স ও সার্জিক্যাল গ্যাস্ট্রোএন্টারোলজিতে উৎকর্ষ কেন্দ্র রয়েছে। এটি ফিজিওথেরাপি, ডার্মাটোলজি, প্লাস্টিক সার্জারি, শিশু নিউরোলজি, শ্বাসযন্ত্র চিকিৎসা, মিনিমালি ইনভেসিভ মেরুদণ্ড সার্জারি, বোন ম্যারো প্রতিস্থাপন, প্রসূতি ও স্ত্রীরোগ, পরিপাক ও লিভার যত্ন, সাধারণ ও ল্যাপারোস্কোপিক সার্জারি, জয়েন্ট রিপ্লেসমেন্ট ও নিউরোসায়েন্সও প্রদান করে। এটি ২০১৯ সালে তার Centre for Robotic Surgery চালু করে এবং ২০১৮ সালে King's College London-এর সহযোগিতায় পার্কিনসন্স রোগের জন্য অ্যাপোমরফিন পেন ও পাম্প থেরাপি চালু করে।\n##technology\nইমেজিং কেন্দ্রটি 10,000+ বর্গফুট জুড়ে একটি 3 Tesla ওয়াইড-বোর MRI এবং কার্ডিয়াক সক্ষমতাসহ একটি 64-স্লাইস PET-CT স্ক্যানারসহ বিস্তৃত। হাসপাতালটি NABH ও NABL দ্বারা স্বীকৃত, এবং Best Hospital for Patient Safety (2021) ও Hospital of the Year in Organ Transplant (2024)-সহ পুরস্কার জিতেছে।\n##international\nহাসপাতালটিতে একটি নিবেদিত International Patient Desk রয়েছে যা বিনামূল্যে বিমানবন্দর পিকআপ ও ড্রপ-অফ, ভিসা সহায়তা, মেডিক্যাল ভ্রমণ বিমা সমন্বয়, দোভাষী ও অনুবাদ, বিদেশি মুদ্রা বিনিময় এবং কাস্টমাইজড খাবার প্রদান করে। এটি Vile Parle West-এ মুম্বাইয়ের দেশীয় ও আন্তর্জাতিক বিমানবন্দরের কাছে অবস্থিত।",
	'apollo-hospitals-greams-road':
		"##history\nApollo Hospitals, Greams Road, ১৯৮৩ সালে ড. প্রতাপ সি. রেড্ডি শুরু করেন ভারতের প্রথম পেশাদারভাবে পরিচালিত ১৫০ শয্যার বেসরকারি হাসপাতাল হিসেবে, এবং দেশের প্রথম কর্পোরেট হাসপাতাল হিসেবে বেসরকারি স্বাস্থ্যসেবার রূপান্তরে গুরুত্বপূর্ণ ভূমিকা পালন করে। ড. রেড্ডিকে পদ্মবিভূষণ দেওয়া হয়েছে এবং তিনটি মিডিয়া হাউস থেকে জীবনব্যাপী কৃতিত্বের পুরস্কার পেয়েছেন। আজ হাসপাতালটিতে ৫৫০টি শয্যা রয়েছে, এটি JCI ও NABH দ্বারা স্বীকৃত এবং ব্যাপকভাবে আন্তর্জাতিক রোগীদের জন্য ভারতের অন্যতম সেরা হাসপাতাল হিসেবে বিবেচিত হয়।\n##specialities\nহাসপাতালটিতে ১২টিরও বেশি উৎকর্ষ কেন্দ্র রয়েছে, Apollo Heart Institute, Institute of Liver Sciences, Institute of Neurosciences, Institute of Colorectal Surgery ও Institute of Robotic Surgery-সহ। এর প্রতিস্থাপন কর্মসূচি লিভার, কিডনি, হৃদয় ও ফুসফুস কভার করে, ভারতের প্রথম সফল প্যানক্রিয়াস প্রতিস্থাপন এবং এশিয়ার প্রথম en-bloc সম্মিলিত হৃদয় ও লিভার প্রতিস্থাপনের মতো মাইলফলকসহ। এটি ভারতের প্রথম হাসপাতাল যা করোনারি অ্যাঞ্জিওপ্লাস্টি, স্টিরিওট্যাকটিক রেডিওথেরাপি ও মস্তিষ্কের টিউমারের জন্য রেডিওসার্জারি চালু করে।\n##technology\nপ্রযুক্তির মধ্যে রয়েছে da Vinci রোবোটিক সার্জিক্যাল সিস্টেম, মেরুদণ্ড সার্জারির জন্য ExcelsiusGPS, রেডিয়েশন থেরাপির জন্য TrueBeam STx, ভারতের প্রথম CyberKnife এবং দক্ষিণ-পূর্ব এশিয়ায় 64-স্লাইস PET-CT ব্যবহার। প্রোটন থেরাপি কেন্দ্রটিকে ভারতের প্রথম এবং দক্ষিণ এশিয়ার সবচেয়ে উন্নত বলে বর্ণনা করা হয়।\n##international\nApollo Chennai আন্তর্জাতিক মেডিক্যাল পরিষেবার জন্য সবচেয়ে সম্ভাবনাময় কোম্পানি হিসেবে স্বীকৃত হয়েছে (MT India Healthcare Awards, 2023)। এটি কেন্দ্রীয় চেন্নাইতে Greams Road-এর কাছে Greams Lane-এ অবস্থিত, হোটেলের কাছাকাছি।",
	'miot-international':
		"##history\nMIOT International, Madras Institute of Orthopaedics and Traumatology, পদ্মশ্রী প্রফেসর ড. পি. ভি. এ. মোহনদাস ১৯৯৯ সালের ১২ ফেব্রুয়ারি একটি ৭০ শয্যার হাসপাতাল হিসেবে শুরু করেন যা অর্থোপেডিক্স ও ট্রমা যত্নে মনোনিবেশ করেছিল। ড. মোহনদাস ভারতে প্রথম হিপ রিপ্লেসমেন্ট সার্জারি সম্পাদন করেন এবং জয়েন্ট রিপ্লেসমেন্টে অগ্রণী কাজের জন্য ১৯৯২ সালে পদ্মশ্রী পান। হাসপাতালটি এখন Manapakkam-এ ৬৩টি বিশেষত্ব ও ২১টি অপারেশন থিয়েটারসহ একটি ১,০০০ শয্যার কোয়াটারনারি-কেয়ার হাসপাতালে পরিণত হয়েছে, ১৩০+ দেশের রোগীদের স্বাগত জানায়।\n##specialities\nMIOT-এর অর্থোপেডিক্স ও জয়েন্ট রিপ্লেসমেন্ট বিভাগ Outlook Health দ্বারা ভারতে প্রথম স্থান পেয়েছে, হিপ, নী ও উপরের অঙ্গের ৪০,০০০+ জয়েন্ট রিপ্লেসমেন্টসহ। মাইলফলকের মধ্যে রয়েছে প্রথম কিহোল সার্জারি, ভারতের প্রথম রক্তের গ্রুপ জুড়ে কিডনি প্রতিস্থাপন, ভারতের প্রথম হ্যাপ্লোআইডেন্টিক্যাল বোন ম্যারো প্রতিস্থাপন এবং এশিয়া প্যাসিফিকের প্রথম TrueBeam STx রেডিওথেরাপি স্থাপনা। ২০১২ সাল থেকে, MIOT International Centre অনকোলজি, রেডিয়েশন অনকোলজি, একটি লিভার প্রতিস্থাপন কেন্দ্র এবং একটি বোন ম্যারো প্রতিস্থাপন কেন্দ্র ধারণ করে, কার্ডিওলজি, নেফ্রোলজি, নিউরোসার্জারি, প্লাস্টিক সার্জারি, শিশুরোগ ও প্রসূতিবিদ্যার পাশাপাশি।\n##technology\nহাসপাতালটি NABH ও NABL দ্বারা স্বীকৃত এবং অর্থোপেডিক্সে Times Healthcare Legends ও চেন্নাইয়ের সেরা মাল্টি-স্পেশালিটি হাসপাতাল (2018), Radio City ICON Award (2019) এবং Times Healthcare Achievers Awards (2020)-সহ পুরস্কার জিতেছে।\n##international\nMIOT ভিসা আমন্ত্রণপত্র, বিনামূল্যে বিমানবন্দর পরিবহন এবং বহুভাষিক দোভাষী সহায়তা প্রদান করে। এটি Mount Poonamallee Road-এ অবস্থিত, চেন্নাইয়ের বিমানবন্দর থেকে খুব দূরে নয়।",
	'gleneagles-global-health-city':
		"##history\nচেন্নাইয়ের Perumbakkam-এ Gleneagles Global Health City IHH Healthcare-এর অংশ এবং ভারতের অন্যতম বৃহত্তম মাল্টি-অর্গান প্রতিস্থাপন ও কোয়াটারনারি-কেয়ার হাসপাতাল, একটি ২১-একর ক্যাম্পাসে। প্রফেসর Mohamed Rela ২০০৯ সালে শুরু করা এর Institute of Liver Disease and Transplantation ১,৫০০-এরও বেশি লিভার প্রতিস্থাপন সম্পন্ন করেছে এবং ভারতের অন্যতম বৃহত্তম লিভার প্রতিস্থাপন কর্মসূচি হিসেবে বিবেচিত হয়। প্রফেসর Rela ৪,০০০-এরও বেশি লিভার প্রতিস্থাপন সম্পন্ন করেছেন এবং একজন পাঁচ দিনের শিশুর লিভার প্রতিস্থাপনের জন্য Guinness Book of Records-এ তালিকাভুক্ত।\n##specialities\nহাসপাতালটিতে ৪০+ বিশেষত্ব রয়েছে এবং অঙ্গ প্রতিস্থাপন, অনকোলজি, হেপাটোলজি, নিউরোসায়েন্স ও ট্রমা যত্নে আন্তর্জাতিকভাবে স্বীকৃত। এটি লিভার, কিডনি, হৃদয়, ফুসফুস ও বোন ম্যারো প্রতিস্থাপন সম্পাদন করে, এবং একদিনে পাঁচটি অঙ্গ প্রতিস্থাপন সম্পাদনকারী দক্ষিণ ভারতের প্রথম, প্রাপ্তবয়স্কদের মধ্যে একটি সোয়াপ লিভার প্রতিস্থাপন ও একটি স্প্লিট-লিভার প্রতিস্থাপন সম্পাদনকারী ভারতের প্রথম, এবং একটি কৃত্রিম ফুসফুস প্রতিস্থাপনকারী ও একটি জরায়ু প্রতিস্থাপন সম্পাদনকারী ভারতের প্রথম বলে জানায়। এর ফুসফুস প্রতিস্থাপন কর্মসূচি ভারতের সেরাগুলোর মধ্যে বিবেচিত হয়, এবং এটি লন্ডনের King's College Hospital-এর সহযোগিতায় লিভার প্রতিস্থাপন সম্পাদন করে।\n##technology\nহাসপাতালটি প্রায় ১,০০০ শয্যার ক্ষমতার কথা জানায় এবং NABH ও NABL দ্বারা স্বীকৃত, খাবারের জন্য হালাল সার্টিফিকেশনসহ।\n##international\nহাসপাতালটির লক্ষ্য বিশেষত মাল্টি-অর্গান প্রতিস্থাপনের জন্য প্রতিযোগিতামূলক দামে আন্তর্জাতিক মান পূরণকারী সুবিধা প্রদান করা। Perumbakkam দক্ষিণ চেন্নাইতে আইটি করিডোরের কাছে অবস্থিত।",
	'fortis-malar-hospital':
		"##history\nAdyar (চেন্নাই)-তে ফোর্টিস মলার হাসপাতাল ১৯৯২ সালে Malar Hospital হিসেবে প্রতিষ্ঠিত হয় এবং ২০০৭ সালে ফোর্টিস হেলথকেয়ারের অংশ হয়ে যায়। এটি ৪০+ বিশেষত্বে যত্ন প্রদানকারী ১৮০ শয্যার একটি টারশিয়ারি-কেয়ার মাল্টিস্পেশালিটি হাসপাতাল। এটি তার Fortis Centre for Heart Failure and Transplant-এর জন্য পরিচিত, যা হার্ট ফেলিওর ব্যবস্থাপনার জন্য ভারতের প্রথম ব্যাপক কেন্দ্র হিসেবে বর্ণিত।\n##specialities\nহাসপাতালের কার্ডিয়াক কর্মসূচি ইন্টারভেনশনাল, ইনভেসিভ, নন-ইনভেসিভ ও শিশু কার্ডিওলজি, কার্ডিওভাস্কুলার সার্জারি ও হৃদ-প্রতিস্থাপন কভার করে। কেন্দ্রটি ৫০+ হৃদ-প্রতিস্থাপন, দীর্ঘমেয়াদি LVAD ইমপ্ল্যান্ট এবং সংকটজনক হার্ট ফেলিওরের জন্য ভেনো-আর্টেরিয়াল ECMO সহায়তা সম্পন্ন করেছে, এবং ভারতের প্রথম সফল Heartmate II LVAD ও HVAD ইমপ্ল্যান্টের কৃতিত্ব এর। কার্ডিয়াক সায়েন্সের পরিচালক ড. কে. আর. বালকৃষ্ণনের ৩০+ বছরের অভিজ্ঞতা রয়েছে, ১৬,০০০+ হৃদ অপারেশন সম্পাদন করেছেন এবং FICCI Special Jury Award পেয়েছেন। হাসপাতালটি নিউরোলজি, নিউরোসার্জারি, অর্থোপেডিক্স, নেফ্রোলজি, স্ত্রীরোগ, গ্যাস্ট্রোএন্টারোলজি, ইউরোলজি, শিশুরোগ ও ডায়াবেটিস যত্নও প্রদান করে।\n##technology\nহাসপাতালটি NABH দ্বারা স্বীকৃত। শয্যা ক্ষমতার সংখ্যা সূত্রভেদে পরিবর্তিত হয়, তাই রোগীদের পরিকল্পনা করার সময় বর্তমান ক্ষমতা নিশ্চিত করা উচিত।\n##international\nহাসপাতালটি বিদেশের রোগীদের চিকিৎসা করে; সাম্প্রতিক একটি কেসে একজন ৪০ বছর বয়সী পাকিস্তানি নাগরিকের সফল হৃদ-প্রতিস্থাপন জড়িত ছিল। Adyar দক্ষিণ চেন্নাইয়ের একটি শান্ত আবাসিক এলাকা।",
	'kauvery-hospital':
		"##history\nAlwarpet-এ Kauvery Hospital, 81, TTK Road-এ, কেন্দ্রীয় চেন্নাইয়ের একটি মাল্টিস্পেশালিটি হাসপাতাল, Kauvery গ্রুপের অংশ, যা তামিলনাড়ু ও কর্ণাটকের ১০টি স্থানে ২,০০০+ শয্যা ধারণ করে। হাসপাতালটিকে Newsweek দ্বারা ভারতের শীর্ষ ২০টি হাসপাতালের মধ্যে একটি হিসেবে বর্ণনা করা হয়, এবং আন্তর্জাতিকভাবে প্রশিক্ষিত সার্জনদের একটি নেটওয়ার্ক গড়ে তুলতে ২৫ বছর ব্যয় করেছে। এর Alwarpet ও Vadapalani হাসপাতাল JCI স্বীকৃতি ধারণ করে, যা ভারতের একমাত্র দ্বৈত 8ম সংস্করণ JCI নেটওয়ার্ক হিসেবে বর্ণিত।\n##specialities\nKauvery-তে কার্ডিয়াক সায়েন্স, নিউরোসায়েন্স, গ্যাস্ট্রোএন্টারোলজি, অঙ্গ প্রতিস্থাপন, অর্থোপেডিক্স ও নারী স্বাস্থ্যে উৎকর্ষ কেন্দ্র রয়েছে। Alwarpet-এ Kauvery Heart Institute জটিল অ্যাঞ্জিওপ্লাস্টি, Impella, হাইব্রিড বাইপাস সার্জারি ও হৃদ-প্রতিস্থাপনে মনোনিবেশ করে। প্রতিস্থাপন সার্জন, হার্ট-ফেলিওর কার্ডিওলজিস্ট, প্রতিস্থাপন পালমোনোলজিস্ট, থোরাসিক অ্যানেস্থেটিস্ট, ইনটেনসিভিস্ট, পারফিউশনিস্ট ও সমন্বয়কারীদের সমন্বয়ে গঠিত এর হৃদয় ও ফুসফুস প্রতিস্থাপন দল ২০২৩ সালে তামিলনাড়ু স্টেট ট্রান্সপ্লান্ট অথরিটি (TRANSTAN) দ্বারা সম্মানিত হয়েছে।\n##technology\nKauvery Institute of Robotic Surgery অনকোলজি, ইউরোলজি, গ্যাস্ট্রোইন্টেস্টাইনাল, কোলোরেক্টাল ও কার্ডিয়াক সার্জারি, লিভার সার্জারি ও কিডনি প্রতিস্থাপনে da Vinci রোবোটিক সার্জারি প্রদান করে। হাসপাতালটিতে Alwarpet ফ্লাইওভারের কাছে একটি সাত তলা ভবনে প্রায় ৩০০টি শয্যা রয়েছে এবং NABH দ্বারা স্বীকৃত।\n##international\nযা অনেক আন্তর্জাতিক রোগীকে Kauvery-তে আকৃষ্ট করে তা হলো এর অত্যন্ত বিশেষায়িত মেডিক্যাল দল। Alwarpet কেন্দ্রীয় চেন্নাইতে হোটেল ও রেস্তোরাঁর কাছে ভালোভাবে অবস্থিত।",
	'manipal-hospital-old-airport-road':
		"##history\nManipal Hospital, Old Airport Road, ১৯৯১ সালে বেঙ্গালুরুতে শহরের প্রথম কর্পোরেট হাসপাতাল হিসেবে চালু হয় এবং Manipal Hospitals নেটওয়ার্কের প্রধান হাসপাতাল ও Manipal Education and Medical Group-এর ভিত্তিপ্রস্তর হয়ে ওঠে। এটি The Week Health Summit 2025-এ Best Multispeciality Hospital (Private) এবং The Week Best Hospitals Awards 2024-এ Best Multi-Speciality Hospital in Bengaluru নামকরণ করা হয়েছে, এবং ২০০৫ সালে Golden Peacock National Quality Award জিতেছে। এটি NABH ও JCI দ্বারা স্বীকৃত।\n##specialities\nহাসপাতালটি অনকোলজি, কার্ডিয়াক সায়েন্স, নিউরোসায়েন্স, গ্যাস্ট্রোএন্টারোলজি, অর্থোপেডিক্স ও অঙ্গ প্রতিস্থাপনে উৎকর্ষ কেন্দ্রসহ ৬০+ সুপার-স্পেশালিটি প্রদান করে। এটি কিডনি, লিভার, প্যানক্রিয়াস, হৃদয়, ফুসফুস ও বোন ম্যারোর জন্য ব্যাপক কর্মসূচিসহ মাল্টি-অর্গান প্রতিস্থাপনের একটি প্রতিষ্ঠিত কেন্দ্র, এবং ভারতে রোবোট-সহায়তায় কিডনি প্রতিস্থাপনের প্রাথমিক গ্রহণের জন্য পরিচিত। বৃহত্তর নেটওয়ার্কের প্রতিস্থাপন কর্মসূচি দেশের বৃহত্তমগুলোর মধ্যে একটি।\n##technology\nহাসপাতালটিতে প্রায় ৬০০+ শয্যা রয়েছে, ১৪৪টি ইনটেনসিভ কেয়ার শয্যাসহ, এবং ২০টি মডুলার অপারেশন থিয়েটার, উন্নত ক্যান্সার যত্ন ও অঙ্গ প্রতিস্থাপন ইউনিটসহ।\n##international\nহাসপাতালটি ৮০+ দেশের রোগীদের সেবা দেয়, শেষ-থেকে-শেষ সহায়তা প্রদান করে: টেলিকনসালটেশনসহ আগমনের আগে পরামর্শ ও চিকিৎসা পরিকল্পনা, মেডিক্যাল ভিসা আমন্ত্রণপত্রসহ ভিসা ও ভ্রমণ সহায়তা, বিমানবন্দর পিকআপ ও ড্রপ-অফ, থাকার ব্যবস্থা, অনুবাদ ও বহুভাষিক দোভাষী। এটি HAL Old Airport Road-এ অবস্থিত।",
	'sakra-world-hospital':
		"##history\nবেঙ্গালুরুতে Sakra World Hospital ২০১৪ সালের ফেব্রুয়ারিতে চালু হয়, যা ভারতের প্রথম জাপানি মাল্টিস্পেশালিটি হাসপাতাল এবং ভারতের প্রথম ১০০% বিদেশি প্রত্যক্ষ বিনিয়োগ হাসপাতাল হিসেবে বর্ণিত, Toyota Tsusho ও জাপানের Secom Hospitals-এর একটি যৌথ উদ্যোগ দ্বারা মালিকানাধীন ও পরিচালিত, চালুর সময় Kirloskar-এর জড়িততাসহ। এটি ভারত ও জাপানের শক্তিকে একত্রিত করে, এবং এর নার্সিং প্রোটোকল ভারতীয় ও জাপানি অনুশীলনের মিশ্রণ। এটি Indian Business Awards থেকে Award for Excellence in Healthcare, স্বাস্থ্য ও পরিবার কল্যাণ মন্ত্রণালয় থেকে জাতীয় স্বীকৃতি এবং QCI থেকে প্রথম National Award for Laboratory Excellence পেয়েছে। এটি AACI স্বীকৃতিও অর্জন করেছে, ৫০০ শয্যার একটি দ্বিতীয় হাসপাতাল ঘোষণা করা হয়েছে।\n##specialities\nহাসপাতালটি নিউরোলজি, কার্ডিওলজি, অর্থোপেডিক্স, প্রসূতি ও স্ত্রীরোগ, রেনাল সায়েন্স, পুনর্বাসন বিজ্ঞান, শিশুরোগ, মেরুদণ্ড সার্জারি, রেডিওলজি, ক্লিনিক্যাল সাইকোলজি, ইন্টার্নাল মেডিসিন, ইএনটি, মাথা ও ঘাড় সার্জারি, ক্যান্সার, রক্তের রোগ, প্লাস্টিক সার্জারি, শ্বাসযন্ত্র চিকিৎসা, রিউমাটোলজি, এন্ডোক্রিনোলজি, ডেন্টিস্ট্রি, ডার্মাটোলজি, সাইকিয়াট্রি, চক্ষুবিদ্যা, ক্রিটিক্যাল কেয়ার, ব্যথার ঔষধ এবং আরও অনেক কিছু প্রদান করে। এটি কার্ডিওলজি, অর্থোপেডিক্স, নিউরোলজি ও অঙ্গ প্রতিস্থাপনের জন্য খ্যাতিমান। Sakra Institute of Rehabilitation Sciences এশিয়ার বৃহত্তম পুনর্বাসন কেন্দ্র এবং একটি বৈশ্বিক মান স্বীকৃতিসহ প্রথম বলে বিবেচিত হয়।\n##technology\nহাসপাতালটিতে ৩৫০টি ভর্তি রোগীর শয্যা রয়েছে, ইমেজিংয়ে MRI, মাল্টিডিটেক্টর CT, 3D ও 4D আল্ট্রাসাউন্ড, ডিজিটাল এক্স-রে, OPG ও হাড়ের খনিজ ঘনত্ব পরিমাপসহ।\n##international\nএকটি নিবেদিত International Patient Services বিভাগ বিদেশ থেকে আসা রোগী ও সঙ্গীদের দেখাশোনা করে, ভিসা ব্যবস্থা, বিমানবন্দর ট্রান্সফার, থাকার ব্যবস্থা, ভাষা ব্যাখ্যা ও ব্যক্তিগতকৃত যত্ন ব্যবস্থাপনাসহ। হাসপাতালটি Outer Ring Road-এ, Marathahalli ও Bellandur-এর কাছে অবস্থিত।",
	'narayana-institute-of-cardiac-sciences':
		"##history\nNarayana Institute of Cardiac Sciences ২০০০ সালে বেঙ্গালুরুর Bommasandra-তে NH Health City-র অংশ হিসেবে চালু করেন হৃদ-সার্জন ড. দেবী শেঠি, নারায়ণ হেলথের প্রতিষ্ঠাতা। এটি নারায়ণ হেলথের প্রধান কার্ডিয়াক কেন্দ্র এবং বিশ্বের অন্যতম বৃহত্তম কার্ডিয়াক হাসপাতাল, একটি ক্যাম্পাসের অংশ যা বিশ্বের অন্যতম বৃহত্তম কার্ডিয়াক যত্ন সাইট হিসেবে বর্ণিত। ইনস্টিটিউটটি ১,০০,০০০-এরও বেশি কার্ডিয়াক প্রক্রিয়া সম্পন্ন করেছে এবং ২৫০+ কার্ডিওলজিস্ট ও কার্ডিয়াক বিশেষজ্ঞের একটি দল রয়েছে। এটি JCI ও NABH দ্বারা স্বীকৃত।\n##specialities\nইনস্টিটিউটটি হৃদ-সার্জারি ও হৃদ-প্রতিস্থাপনে বিশেষায়িত এবং ইলেক্ট্রোফিজিওলজি পরিষেবা, বাম ভেন্ট্রিকুলার সহায়ক যন্ত্র (LVAD) ইমপ্ল্যান্টেশন, ট্রান্সক্যাথেটার অর্টিক ভাল্ভ ইমপ্ল্যান্টেশন (TAVI) এবং কাঠামোগত হৃদরোগের জন্য একটি কর্মসূচিও প্রদান করে। এটি প্রতিদিন ৪০+ হৃদ-সার্জারি সম্পাদন করে, প্রায় ১৬টি শিশু হৃদ-সার্জারিসহ।\n##technology\nসুবিধাটিতে প্রায় ২০টি কার্ডিয়াক অপারেশন থিয়েটার রয়েছে, দুটি উন্নত রোবোটিক থিয়েটারসহ, এবং বেশ কয়েকটি ডিজিটাল ক্যাথ ল্যাব, ইন্টারভেনশনাল প্রক্রিয়া ও জটিল হৃদ-সার্জারির জন্য একটি হাইব্রিড ল্যাবসহ। এতে পোস্ট-অপারেটিভ যত্নের জন্য প্রায় ২০০টি ক্রিটিক্যাল কেয়ার শয্যা রয়েছে।\n##international\nইনস্টিটিউটটি Kempegowda আন্তর্জাতিক বিমানবন্দর থেকে প্রায় ৫০ কিমি দূরে, ভারতের অন্যান্য অঞ্চল ও বিদেশ থেকে ভ্রমণকারী রোগীদের জন্য সুবিধাজনক। এটি Hosur Road-এ Electronic City-র কাছে অবস্থিত।",
	'fortis-hospital-bannerghatta-road':
		"##history\nফোর্টিস হাসপাতাল, Bannerghatta Road, ২০০৬ সালে খোলে এবং দক্ষিণ ভারতে ফোর্টিস হেলথকেয়ারের প্রধান মাল্টিস্পেশালিটি হাসপাতাল, IIM Bangalore-এর বিপরীতে। এটি NABH (চারবার) ও JCI (পাঁচবার) দ্বারা স্বীকৃত এবং কর্ণাটকের প্রথম হাসপাতাল বলে জানা যায় যা JCI স্বীকৃতি অর্জন করে। এটি AHPI পুরস্কার, National Energy Conservation Award (2014), Asian Patient Safety Award এবং যত্নে উৎকর্ষের জন্য আন্তর্জাতিক মেডিক্যাল ট্যুরিজম স্বীকৃতিসহ পুরস্কার জিতেছে, এবং The Week দ্বারা বেঙ্গালুরুর সেরা মাল্টি-স্পেশালিটি হাসপাতালগুলোর মধ্যে স্থান পেয়েছে।\n##specialities\nহাসপাতালটি প্রায় ৪০টি মেডিক্যাল ক্ষেত্র জুড়ে সুপার-স্পেশালিটি টারশিয়ারি যত্ন প্রদান করে, কার্ডিওলজি ও হৃদ-সার্জারি, নিউরোলজি ও নিউরোসার্জারি, অনকোলজি, অর্থোপেডিক্স, অঙ্গ প্রতিস্থাপন, গ্যাস্ট্রোএন্টারোলজি, শিশুরোগ ও ক্রিটিক্যাল কেয়ারে উৎকর্ষ কেন্দ্রসহ। এর অনকোলজি বিভাগ উন্নত রেডিওথেরাপি, কেমোথেরাপি, টিউমার বোর্ড ও বোন ম্যারো প্রতিস্থাপন, রোবোটিক ক্যান্সার সার্জারি এবং প্রস্টেট ক্যান্সারের জন্য HIFU প্রদান করে, PET-CT, PET-MR, 3T MRI ও মলিকুলার ডায়াগনস্টিকস দ্বারা সমর্থিত। এর কার্ডিয়াক কর্মসূচি অ্যাঞ্জিওপ্লাস্টি, বাইপাস, ভাল্ভ রিপেয়ার, ইলেক্ট্রোফিজিওলজি, হাইব্রিড কার্ডিয়াক সার্জারি ও হৃদয়-ফুসফুস প্রতিস্থাপন অন্তর্ভুক্ত করে, এবং Fortis Institute of Robotic Surgery একটি উৎকর্ষ কেন্দ্র।\n##technology\nহাসপাতালটিতে প্রায় ২৮০টি শয্যা, ১৫০+ ডাক্তার ও ৮০০ প্যারামেডিক্যাল কর্মী রয়েছেন, জরুরি যত্ন, অঙ্গ প্রতিস্থাপন ও প্রতিরোধমূলক যত্নসহ।\n##international\nফোর্টিস Bannerghatta Road মেডিক্যাল ভিসা সহায়তা, অনুবাদক ও কনসিয়ার্জ সহায়তাসহ আন্তর্জাতিক রোগী পরিষেবা প্রদান করে, এবং ১৭৫+ দেশের রোগীদের সহায়তা করার কথা জানায়। এটি দক্ষিণ বেঙ্গালুরুতে Bannerghatta Road-এ অবস্থিত।",
	'aster-cmi-hospital':
		"##history\nবেঙ্গালুরুর Hebbal-এ Aster CMI হাসপাতাল Aster DM Healthcare-এর অংশ, এশিয়ার অন্যতম বৃহত্তম স্বাস্থ্যসেবা নেটওয়ার্ক, নয়টি দেশে কার্যক্রম চালায়। উৎস তার প্রতিষ্ঠার বছর নিয়ে ভিন্নমত পোষণ করে, তাই এটিকে ২০১০-এর দশকের একটি হাসপাতাল হিসেবে বর্ণনা করা ভালো। এটি NABH ও NABL দ্বারা স্বীকৃত এবং প্রায় ৫০০টি শয্যা রয়েছে, প্রাথমিক থেকে কোয়াটারনারি যত্ন পর্যন্ত। এটি বেঙ্গালুরুর প্রথম হাসপাতাল যা কর্ণাটক রাজ্যের কিডনি প্রতিস্থাপন কেন্দ্র হিসেবে নির্বাচিত হয়, এবং কর্ণাটকের প্রথম হাসপাতাল যা প্রাথমিক ইমিউন ঘাটতির জন্য উৎকর্ষ কেন্দ্র হিসেবে FPID (মার্কিন যুক্তরাষ্ট্র) দ্বারা সার্টিফাইড হয়।\n##specialities\nAster CMI কার্ডিয়াক সায়েন্স, নিউরোসায়েন্স, গ্যাস্ট্রোএন্টারোলজি, সমন্বিত লিভার যত্ন, অঙ্গ প্রতিস্থাপন, ইউরোলজি ও নেফ্রোলজি, অর্থোপেডিক্স, নারী স্বাস্থ্য এবং শিশু ও কিশোর স্বাস্থ্যে উৎকর্ষ কেন্দ্র প্রদান করে, এক ছাদের নিচে ৩৮+ বিশেষত্বসহ। এর প্রতিস্থাপন কর্মসূচি এখন পর্যন্ত মোট ১,০০০+ কিডনি প্রতিস্থাপন সম্পন্ন করেছে, da Vinci সার্জিক্যাল রোবট ব্যবহার করে ৫৪টি রোবোটিক কিডনি প্রতিস্থাপনসহ। Aster International Institute of Oncology প্রোটন থেরাপি, রোবোটিক সার্জারি, HIPEC ও মলিকুলার টিউমার প্রোফাইলিং প্রদান করে।\n##technology\nহাসপাতালটি বিমানবন্দর সড়কে Hebbal এলাকায় অবস্থিত, এবং এর ইউরোলজি ও নেফ্রোলজি বিভাগ Times of India-র ক্রিটিক্যাল কেয়ার সমীক্ষায় বেঙ্গালুরুর সেরাগুলোর মধ্যে স্থান পেয়েছে।\n##international\nআন্তর্জাতিক রোগীদের জন্য, Aster CMI নিবেদিত সমন্বয়, বিমানবন্দর ট্রান্সফার, বিদেশি ভাষার দোভাষী ও ভিসা সহায়তা প্রদান করে। Hebbal কেন্দ্রীয় বেঙ্গালুরু ও Kempegowda আন্তর্জাতিক বিমানবন্দরের মধ্যবর্তী পথে অবস্থিত।",
	'apollo-hospitals-jubilee-hills':
		"##history\nApollo Hospitals, Jubilee Hills, ১৯৮৮ সালে প্রতিষ্ঠিত, হায়দরাবাদে Apollo-র প্রধান হাসপাতাল এবং JCI স্বীকৃতি ধারণ করে। এটি ভারত সরকার কর্তৃক একটি শীর্ষস্থানীয় মেডিক্যাল ট্যুরিজম হাসপাতাল হিসেবে সম্মানিত হয়েছে এবং FICCI Healthcare Excellence Award পেয়েছে। এটি ২০০৫ সালে ভারতের প্রথম PET-CT স্ক্যানার চালু করে, সম্পূর্ণ শোষণযোগ্য স্টেন্টসহ ভারতের প্রথম করোনারি অ্যাঞ্জিওপ্লাস্টি সম্পাদন করে, এবং ৯৯%-এরও বেশি রিপোর্ট করা সাফল্যের হারসহ ১,৫০,০০০-এরও বেশি হৃদ-সার্জারি সম্পন্ন করেছে। এটি ৭০০-এরও বেশি কক্লিয়ার ইমপ্ল্যান্টও সম্পন্ন করেছে।\n##specialities\nহাসপাতালটি ১২টি উৎকর্ষ কেন্দ্র পরিচালনা করে। কার্ডিয়াক সায়েন্স কেন্দ্রে তিনটি ক্যাথ ল্যাব এবং নিবেদিত কার্ডিয়াক অপারেশন থিয়েটার রয়েছে, রোবোট-সহায়তায় কার্ডিয়াক সার্জারি, TAVI ও জটিল করোনারি ইন্টারভেনশনসহ। ক্যান্সার কেন্দ্রটি ৩৫ বছরের অভিজ্ঞতার উপর নির্ভর করে এবং রোবোটিক অনকো-সার্জারি প্রদান করে। নিউরোসায়েন্স একটি ইন্ট্রা-অপারেটিভ MRI স্যুট, নিউরো-নেভিগেশন ও স্পাইনাল রোবোটিক্সসহ সজ্জিত। প্রতিস্থাপন দল লিভার, কিডনি, হৃদয় ও বোন ম্যারো প্রতিস্থাপন পরিচালনা করে, এবং Apollo গ্রুপ ৪৩,০০০-এরও বেশি অঙ্গ প্রতিস্থাপন সম্পন্ন করেছে।\n##technology\nহাসপাতালটিতে প্রায় ৫৫০টি শয্যা রয়েছে এবং JCI, NABH ও NABL দ্বারা স্বীকৃত। এটি Road No. 72, Film Nagar, Jubilee Hills-এ অবস্থিত।\n##international\nহাসপাতালটি মাসে ৮০০-এরও বেশি আন্তর্জাতিক রোগী পরামর্শ পরিচালনা করে, যুক্তরাষ্ট্র, UAE, তানজানিয়া, কেনিয়া ও ওমানসহ দেশের রোগীদের নিয়ে। একটি নিবেদিত আন্তর্জাতিক রোগী পরিষেবা দল মেডিক্যাল ভিসা, ভ্রমণ ব্যবস্থা, থাকার ব্যবস্থা ও অনুবাদে সহায়তা করে।",
	'continental-hospitals':
		"##history\nContinental Hospitals ২০১৩ সালের এপ্রিলে ড. গুরু এন. রেড্ডি হায়দরাবাদের Financial District (Nanakramguda, Gachibowli)-এ প্রতিষ্ঠা করেন। এটি ১৮টি তলা ও ১৪ লক্ষ বর্গফুট জুড়ে বিস্তৃত ৫৮৫ শয্যার একটি হাসপাতাল, JCI, NABH ও NABL দ্বারা স্বীকৃত, এবং ভারতের প্রথম LEED-যোগ্য সুপার-স্পেশালিটি হাসপাতাল, সবুজ অপারেশন থিয়েটার ও লেভেল 3 NICU ও PICU সহ। এটি প্রযুক্তি গ্রহণে ভারতের সেরা হাসপাতালের জন্য ASSOCHAM Award 2022 জিতেছে।\n##specialities\nহাসপাতালটি ৫০+ বিশেষত্ব প্রদান করে এবং জটিল অঙ্গ প্রতিস্থাপন, কার্ডিয়াক সায়েন্স, নিউরোসায়েন্স, অনকোলজি, গ্যাস্ট্রো সায়েন্স ও অর্থোপেডিক্সের জন্য পরিচিত। ২০২৩ সালের এপ্রিলে, ড. প্রদীপ রাচাকোন্ডা পরিচালিত সার্জনদের দল, ড. সুধীর শ্রীবাস্তবের নির্দেশনায়, SSI Mantra রোবট দিয়ে ভারতের প্রথম রোবট-সহায়তায় করোনারি আর্টারি বাইপাস গ্রাফট (CABG) সার্জারি সম্পাদন করে। এর প্রতিস্থাপন বিভাগ লিভার, কিডনি, হৃদয়, ফুসফুস ও বোন ম্যারো প্রতিস্থাপন পরিচালনা করে, উন্নত ICU ও প্রতিস্থাপন-পরবর্তী পুনর্বাসন দ্বারা সমর্থিত।\n##technology\nহাসপাতালটিতে ১৬টি মডুলার সবুজ অপারেশন থিয়েটার ও ৯০টি একক-কক্ষ ICU শয্যা রয়েছে, এবং da Vinci ও অন্যান্য রোবোটিক প্ল্যাটফর্মে প্রশিক্ষিত সার্জন।\n##international\nContinental-এ আন্তর্জাতিক রোগীদের জন্য একটি নিবেদিত এলাকা এবং একটি স্বাস্থ্য-চেক লাউঞ্জ রয়েছে। এটি হায়দরাবাদের আইটি করিডোরের কাছে Financial District-এ অবস্থিত, বিমানবন্দর থেকে প্রায় ৩০-৪৫ মিনিট।",
	'yashoda-hospitals-somajiguda':
		"##history\nইয়াশোদা হাসপাতাল, Somajiguda, ইয়াশোদা গ্রুপের প্রথম হাসপাতাল এবং ১৯৯৪ সালে শুরু হয়, ড. জি. সুরেন্দর রাও ১৯৮৯ সালে একটি ছোট ক্লিনিক স্থাপনের পর। তিন দশক ধরে গ্রুপটি Somajiguda, Secunderabad, Malakpet ও Hitec City-তে শাখাসহ সম্প্রসারিত হয়েছে। Somajiguda ইউনিটটি AHPI দ্বারা একটি Patient Friendly Hospital হিসেবে স্বীকৃত, এবং গ্রুপটি ভারত সরকার দ্বারা ক্যাডেভারিক অঙ্গ প্রতিস্থাপনে প্রথম এবং Times Healthcare Achievers পুরস্কারে মাল্টিস্পেশালিটি হাসপাতালে প্রথম স্থান পেয়েছে।\n##specialities\nহাসপাতালটিতে ৪০০+ শয্যা, প্রায় ২৫০ জন ডাক্তার ও ৫০০ জন নার্স রয়েছেন। এর উৎকর্ষ কেন্দ্রগুলো হৃদয় ও CT সার্জারি, নিউরোসায়েন্স, ক্যান্সার, লিভার ও মাল্টি-অর্গান প্রতিস্থাপন, হাড় ও জয়েন্ট, নেফ্রোলজি, রোবোটিক সায়েন্স, মেরুদণ্ড সার্জারি, মা ও শিশু যত্ন ও উর্বরতা কভার করে, ইএনটি ও স্ত্রীরোগ থেকে প্লাস্টিক সার্জারি, নিউক্লিয়ার মেডিসিন ও বেরিয়াট্রিক সার্জারি পর্যন্ত একটি খুব বিস্তৃত বিভাগের তালিকাসহ। গ্রুপের প্রতিস্থাপন মাইলফলকের মধ্যে রয়েছে তেলুগু রাজ্যে প্রথম ফুসফুস প্রতিস্থাপন (2012) এবং একটি সম্মিলিত হৃদয়-ফুসফুস প্রতিস্থাপন (2017)।\n##technology\nল্যাবরেটরি, ডায়াগনস্টিক পরিষেবা ও ফার্মেসি সার্বক্ষণিক পরিচালিত হয়। হাসপাতালটি NABH স্বীকৃত এবং অঞ্চলের প্রথম হাসপাতাল যা রোবোটিক সার্জারি চালু করে।\n##international\nইয়াশোদা আন্তর্জাতিক রোগী পরিষেবা প্রদান করে, এর প্রতিস্থাপন কর্মসূচি ভারতের শীর্ষ মাল্টি-অর্গান কর্মসূচির মধ্যে স্থান পেয়েছে, ডায়ালাইসিস, লিভার ও কিডনি রোগ এবং শিশু প্রতিস্থাপনের জন্য একটি বহু-শাখা দলসহ। Somajiguda কেন্দ্রীয় হায়দরাবাদে Raj Bhavan Road-এ অবস্থিত।",
	'global-hospitals-hyderabad':
		"##history\nLakdi-ka-pul-এ Gleneagles Global Hospitals, যা Global Hospitals নামে পরিচিত, হায়দরাবাদে প্রথম Gleneagles Global হাসপাতাল খোলা হয় এবং ড. কে. রবীন্দ্রনাথ ১৯৯৯ সালে প্রতিষ্ঠিত Global Hospitals Group-এর অন্তর্গত। এটি তৎকালীন অন্ধ্রপ্রদেশ ও তেলেঙ্গানা রাজ্যে প্রথম হৃদ-প্রতিস্থাপনে অগ্রণী ছিল, অঞ্চলের প্রথম বোন ম্যারো প্রতিস্থাপন ও প্রথম যমজ কিডনি প্রতিস্থাপন সম্পাদন করে, এবং ভারতের প্রথম সফল স্প্লিট ও অক্সিলারি লিভার প্রতিস্থাপনের কথা জানায়। এটি ২০২১ সালের Times of India সমীক্ষায় হায়দরাবাদের দ্বিতীয়-সেরা মাল্টিস্পেশালিটি হাসপাতাল এবং দক্ষিণ ভারতের শীর্ষ ১০-এর মধ্যে স্থান পেয়েছে।\n##specialities\nহাসপাতালটি লিভার, কিডনি, হৃদয় ও ফুসফুস প্রতিস্থাপনের জন্য পরিচিত, এবং হেপাটোলজি, নেফ্রোলজি, বেরিয়াট্রিক্স, গ্যাস্ট্রোএন্টারোলজি, মাল্টি-অর্গান প্রতিস্থাপন, এস্থেটিক ও পুনর্গঠনমূলক সার্জারি, অনকোলজি, কার্ডিয়াক সায়েন্স, শিশুরোগ, সাইকিয়াট্রি, এন্ডোক্রিনোলজি, ইএনটি, অর্থোপেডিক্স, মেরুদণ্ড সার্জারি, গ্যাস্ট্রো সায়েন্স, সাধারণ ও ল্যাপারোস্কোপিক সার্জারি এবং শ্বাসযন্ত্র চিকিৎসাও প্রদান করে।\n##technology\nহাসপাতালটিতে প্রায় ১৫০টি শয্যা ও ছয়টি অপারেশন থিয়েটার রয়েছে, রোবোটিক ও মিনিমাল-অ্যাক্সেস সক্ষমতাসহ, এবং একাধিক ICU, একটি সার্জিক্যাল ICU, CT-ICU, স্টেপ-ডাউন ICU, লিভার ICU ও প্রতিস্থাপন-পরবর্তী ইউনিটসহ। এটি NABH ও NABL দ্বারা স্বীকৃত।\n##international\nহাসপাতালটি Gleneagles Global গ্রুপের মাধ্যমে আন্তর্জাতিক রোগী সহায়তা প্রদান করে। Lakdi-ka-pul কেন্দ্রীয় হায়দরাবাদের একটি অবস্থান, Lakdi-ka-pul মেট্রো স্টেশনের কাছে।",
	'kims-hospitals-secunderabad':
		"##history\nKIMS Hospitals, Secunderabad, ২০০৪ সালে Krishna Institute of Medical Sciences গ্রুপের প্রধান হাসপাতাল হিসেবে খোলে, একটি ১,০০০ শয্যার টারশিয়ারি ও কোয়াটারনারি-কেয়ার হাসপাতাল, ভারতের বৃহত্তম বেসরকারি হাসপাতালগুলোর একটি। গ্রুপটি ২০০০ সালে কার্ডিও-থোরাসিক সার্জন ড. ভাস্কর রাও বোল্লিনেনি প্রতিষ্ঠা করেন, যিনি ২৫ বছরে ৩০,০০০-এরও বেশি সার্জারি সম্পন্ন করেছেন এবং ২০০৭ সালে Rajiv Gandhi Aarogyasri প্রকল্প প্রণয়নে গুরুত্বপূর্ণ ভূমিকা পালন করেছিলেন। গ্রুপটির এখন দুই ডজনেরও বেশি হাসপাতাল রয়েছে, এবং এর নির্বাহী পরিচালক ও CEO হলেন ড. অভিনয় বোল্লিনেনি।\n##specialities\nহাসপাতালটি ২৫+ বিশেষত্ব ও সুপার-স্পেশালিটি প্রদান করে, কার্ডিওলজি, গ্যাস্ট্রোএন্টারোলজি ও হেপাটোলজি, নিউরোসায়েন্স, অঙ্গ প্রতিস্থাপন, অনকোলজি, অর্থোপেডিক্স, ইউরোলজি, উর্বরতা, রেনাল সায়েন্স ও মা-শিশু যত্নসহ। এর নিউরোসায়েন্স কেন্দ্র মস্তিষ্কের টিউমার, মেরুদণ্ডের বিকৃতি, পার্কিনসন্স রোগের জন্য ডিপ ব্রেন স্টিমুলেশন ও স্ট্রোক ব্যবস্থাপনা পরিচালনা করে, এবং KIMS Advanced Gastroenterology and Endoscopy (KAGE) কেন্দ্র জটিল পরিপাক ব্যাধি, লিভার রোগ ও POEM প্রক্রিয়ার চিকিৎসা করে।\n##technology\nপ্রতিস্থাপন কর্মসূচি হৃদয়, ফুসফুস, লিভার, কিডনি ও বোন ম্যারো কভার করে, উন্নত এক্স-ভিভো পারফিউশনসহ। হৃদয় ও ফুসফুস প্রতিস্থাপন কেন্দ্র ২০১২ সালে তার প্রথম হৃদ-প্রতিস্থাপন সম্পন্ন করে এবং প্রতি বছর প্রায় ৭৫টি হৃদয় ও ফুসফুস প্রতিস্থাপন সম্পাদন করে, এবং হাসপাতালটি ২০১৯ সালে ১,০০০টি কিডনি প্রতিস্থাপন রেকর্ড করেছে। এটি NABH দ্বারা স্বীকৃত এবং ISO 9001:2015 সার্টিফিকেশন ধারণ করে।\n##international\nKIMS Secunderabad কেন্দ্রীয় Secunderabad-এ Minister Road-এ অবস্থিত, Secunderabad রেলওয়ে স্টেশনের কাছাকাছি।",
};
